NAME = 'Est: Estonian Bible'
BOOK = 'Luke'

CHAPTERS = {
    1: {
        1: 'Et juba mitmed on võtnud kätte kirjutada loo neist asjust, mis meie seas tõsikindlalt on sündinud,',
        2: 'nõnda nagu meile on jutustanud need, kes ise on seda näinud algusest ja on olnud sõna sulased,',
        3: 'siis olen minagi arvanud heaks algusest peale kõike hoolega uurida ja järgemööda kirja panna sinule, kõrgeauline Teofllos,',
        4: 'et sa õpiksid tundma nende asjade kindla tõe, mida sulle on õpetatud.',
        5: 'Heroodese, Judea kuninga ajal oli preester, nimega Sakarias, Abija järjekorrast, ja temal oli naine Aaroni tütardest, ja selle nimi oli Eliisabet.',
        6: 'Nad olid mõlemad õiged Jumala ees ja elasid kõigis käskudes ja Issanda seadustes laitmatult.',
        7: 'Ja neil ei olnud last, sest Eliisabet oli sigimatu ja nad mõlemad olid väga elatanud.',
        8: 'Aga sündis, kui ta oma teenistuse järjekorras oli preestritalitusi toimetamas Jumala ees,',
        9: 'et preestriameti kombe järele langes liisk temale minna suitsutama, ja ta läks Issanda templisse.',
        10: 'Ja kõik rahvahulk oli väljas palvetamas suitsutuse tunnil.',
        11: 'Seal ilmus temale Issanda Ingel, seistes suitsutusaltari paremal pool.',
        12: 'Teda nähes Sakarias ehmus ja hirm valdas teda.',
        13: 'Aga Ingel ütles talle: "Ära karda, Sakarias, sest su palvet on kuuldud ja su naine Eliisabet toob sulle ilmale poja, ja sa paned temale nimeks Johannes.',
        14: 'Ja temast on sul rõõm ning hea meel, ja paljud rõõmustuvad tema sündimisest.',
        15: 'Sest ta peab suur olema Issanda ees; ja viina ega vägijooki ei joo ta mitte, ja ta täitub Püha Vaimuga juba oma ema ihus;',
        16: 'ja ta pöörab palju Iisraeli lapsi Issanda, nende Jumala poole;',
        17: 'ja ta käib Tema eel Eeiija vaimus ja väes, et käänata isade südamed laste poole ja sõnakuulmatud õigete meelsuse poole, et soetada Issandale valmistatud rahvast!"',
        18: 'Ja Sakarias ütles Inglile: "Millest ma seda võin ära tunda? Mina olen ju vana ja mu naine on oma päevade poolest väga elatanud!"',
        19: 'Ingel vastas ning ütles temale: "Mina olen Gabriel, kes seisab Jumala ees, ja ma olen läkitatud rääkima sinuga ja kuulutama sulle seda rõõmusõnumit!',
        20: 'Ja vaata, sa jääd keeletumaks ega saa rääkida päevani, mii see sünnib, sellepärast et sa ei ole uskunud mu sõnu, mis lähevad täide omal ajal!"',
        21: 'Ja rahvas oli ootamas Sakariast ja pani imeks, et ta nii kaua viibis templis.',
        22: 'Aga väljudes ta ei saanud nendega rääkida. Siis nad said aru, et ta templis oli näinud nägemust. Ja tema andis neile käega märku ning jäi keeletumaks.',
        23: 'Ja kui tema teenistuskorra päevad täis said, siis ta läks koju.',
        24: 'Aga pärast neid päevi sai tema naine Eliisabet käima peale ja pidas ennast varjul viis kuud, üteldes:',
        25: '"Nõnda on Issand mulle teinud neil päevil, mil Tema on vaadanud minu peale, et minult ära võtta mu teotus inimeste seas!"',
        26: 'Aga kuuendas kuus läkitas Jumal Ingel Gabrieli Galilea linna, mille nimi on Naatsaret,',
        27: 'Neitsi juure, Kes oli kihlatud Joosepi-nimelise mehega Taaveti soost. Ja neitsi nimi oli Maarja.',
        28: 'Ja tulles sisse Tema juure, ütles Ingel: "Tere, Sa armuleidnu, Issand olgu Sinuga!"',
        29: 'Aga Tema ehmus väga sellest sõnast ja mõtles, mis see teretus võiks tähendada.',
        30: 'Siis Ingel ütles temale: "Ära karda, Maarja, sest Sa oled leidnud armu Jumala juures!',
        31: 'Ja vaata, Sa saad käima peale ning tood ilmale Poja ja paned Temale nimeks Jeesus.',
        32: 'Tema saab suur olema ja Teda peab hüütama Kõigekõrgema Pojaks, ja Issand Jumal annab Temale Ta isa Taaveti aujärje,',
        33: 'ja Ta valitseb igavesti Jaakobi soo üle ning Tema Kuningriigil ei ole otsa!"',
        34: 'Aga Maarja ütles Inglile: "Kuidas see võib sündida, kuna Ma mehest ei tea?"',
        35: 'ka Püha, Kes Sinust sünnib, nimetatama Jumala Pojaks.',
        36: 'Ja vaata, Su sugulane Eliisabet, temagi on pojaga käima peal oma vanas eas, ja see on kuues kuu temal, keda üteldi olevat sigimatu,',
        37: 'sest Jumalal ei ole ükski asi võimatu!"',
        38: 'Aga Maarja ütles: "Vaata, siin on Issanda Ümmardaja; Mulle sündigu su sõna järele!" Ja Ingel läks ära Tema juurest.',
        39: 'Neil päevil asus Maarja teele ja läks rutuga mägestikku Juuda linna.',
        40: 'Ja Ta tuli Sakariase kotta ja teretas Eliisabetti.',
        41: 'Ja sündis, kui Eliisabet kuulis Maarja teretust, et laps hüppas tema ihus. Ja Eliisabet sai täis Püha Vaimu',
        42: 'ja hüüdis suure häälega ning ütles: "Õnnistatud oled Sina naiste seas ja õnnistatud on Sinu ihu sugu!',
        43: 'Kust see tuleb, et minu Issanda Ema on tulnud minu juure?',
        44: 'Sest vaata, kui Su teretuse hääl kostis mu kõrvu, siis hüppas lapsuke suurest rõõmust mu ihus!',
        45: 'Ja õnnis see, kes on uskunud, et läheb täide, mis Issand Temale on ütelnud!"',
        46: 'Siis Maarja ütles: "Mu hing ülistab väga Issandat',
        47: 'ja Mu vaim rõõmutseb Jumalas, Minu Õnnistegijas;',
        48: 'sest Ta on vaadanud oma Ümmardaja alanduse peale! Vaata, nüüdsest peake kiidavad Mind õndsaks kõik sugupõlved,',
        49: 'sest Minule on teinud suuri asju Vägev, ja Tema nimi on püha,',
        50: 'ja Tema halastus kestab põlvest põlve neile, kes Teda kardavad!',
        51: 'Ta on Oma käsivarrega teinud võimsa teo, Ta on pillutanud need, kes on suurelised oma südame meele poolest;',
        52: 'Ta on tõuganud maha vägevad aujärgedelt ja ülendanud alandlikud;',
        53: 'näljased on Ta täitnud heade andidega, aga rikkad tühjalt minema saatnud;',
        54: 'Ta on vastu võtnud Oma sulase Iisraeli, meele tuletades Oma halastust,',
        55: 'nõnda nagu Ta on rääkinud meie isadele, Aabrahamile ja tema soole kuni igavikuni!"',
        56: 'Ja Maarja jäi tema juure umbes kolm kuud ja läks siis tagasi koju.',
        57: 'Aga Eliisabeti mahasaamise aeg tuli kätte, ja ta tõi poja ilmale.',
        58: 'Kui tema üleaedsed ja sugulased kuulsid, et Issand oli temale osutanud suurt halastust, olid nad rõõmsad ühes temaga.',
        59: 'Ja nad tulid kaheksandal päeval lapsukest ümber lõikama ja nimetasid tema ta isa järele Sakariaseks.',
        60: 'Aga tema ema kostis ning ütles: "Ei sugugi, vaid tema nimi peab olema Johannes!"',
        61: 'Kuid nemad ütlesid temale: "Su suguvõsas pole ühtki, keda hüütakse selle nimega!"',
        62: 'Ja viibates isale küsisid nad, kuidas tema tahaks teda nimetada.',
        63: 'Tema nõudis lauakese ja kirjutas selle peale nõnda: "Johannes on tema nimi." Ja nad kõik panid seda imeks.',
        64: 'Aga sedamaid läks tema suu ning keel lahti, ja ta hakkas rääkima, kiites Jumalat.',
        65: 'Ja kartus tuli kõikidele, kes elasid nende ümbruses, ja kõigist neist asjust kõneldi Juuda mägestikus.',
        66: 'Ja kõik, kes seda kuulsid, võtsid seda oma südamesse ja ütlesid: "Mis saab küll sellest lapsest?" Sest Issanda käsi oli temaga.',
        67: 'Ja Sakarias, tema isa, sai täis Püha Vaimu ja hakkas ennustama, üteldes:',
        68: '"Kiidetud olgu Issand, Iisraeli Jumal, et Ta on tulnud katsuma Oma rahvast ja on saatnud Oma rahvale lunastuse',
        69: 'ning on meile äratanud päästesarve Taaveti, Oma sulase kojast',
        70: '- nõnda nagu Ta maailma ajastu algusest on rääkinud Oma pühade prohvetite suu kaudu -',
        71: 'päästu meie vaenlasist ja kõigi nende käest, kes meid vihkavad,',
        72: 'et osutada halastust meie esiisadele ja tuletada meele oma püha lepingut,',
        73: 'seda vannet, mille Ta vandus meie isale Aabrahamile,',
        74: 'et ta laseb meid päästetuina meie vaenlaste käest kartmatult',
        75: 'Teda teenida pühaduses ja õiguses Tema ees kogu meie eluaja.',
        76: 'Ja sina, lapsuke, sind peab hüütama Kõigekõrgema prohvetiks, sest sina lähed Issanda palge eel valmistama Tema teid,',
        77: 'et anda Tema rahvale pääste tunnetus nende pattude andeksandmises',
        78: 'meie Jumala südamliku halastuse läbi, millega meid on tulnud katsuma päevatõus kõrgest,',
        79: 'paistma meile, kes istume pimeduses ja surma varjus, ja juhtima meie jalgu rahuteele!"',
        80: 'Aga lapsuke kasvas ja sai tugevaks vaimus. Ja ta oli kõrves selle päevani, mil ta esines Iisraelile.',
    },
    2: {
        1: 'Neil päevil sündis, et keiser Augustus andis käsu üles kirjutada kogu maailm.',
        2: 'See üleskirjutus oli esimene ja toimus, kui Küreenius oli Süüria maavalitseja.',
        3: 'Ja kõik läksid endid laskma kirja panna, igaüks oma linna.',
        4: 'Siis läks ka Joosep Galileast Naatsareti linnast üles Juudamaale Taaveti linna, mida hüütakse Petlemaks, sest ta oli pärit Taaveti kojast ning soost,',
        5: 'ennast laskma kirja panna ühes Maarja, oma kihlatud naisega, kes oli käima peal.',
        6: 'Aga nende seal olles sai aeg täis, et Maarja pidi maha saama,',
        7: 'ja Ta tõi ilmale Oma esimese Poja ja mähkis Ta mähkmetesse ja asetas Ta sõime, sest neil polnud muud aset majas.',
        8: 'Ja seal paigus oli karjaseid väljal öitsis pidamas valvet öösel oma karja juures.',
        9: 'Ja Issanda Ingel astus nende ette ja Issanda auhiilgus paistis nende ümber, ja nemad kartsid üliväga.',
        10: 'Ja Ingel ütles neile: "Ärge kartke! Sest vaata, ma kuulutan teile suurt rõõmu, mis saab osaks kõigele rahvale:',
        11: 'sest teile on täna Taaveti linnas sündinud Õnnistegija, Kes on Issand Kristus!',
        12: 'Ja see olgu teile tunnuseks: te leiate lapse mähitud ja sõimes magavat!"',
        13: 'Ja äkitselt oli Ingliga ühes taeva sõjaväe hulk; need kiitsid Jumalat ning ütlesid:',
        14: '"Au olgu Jumalale kõrges ja maa peal rahu inimeste seas, kelledest Temal on hea meel!"',
        15: 'Kui siis Inglid olid läinud nende juurest ära taevasse, ütlesid karjased üksteisele: "Läki nüüd Petlemma ja vaadakem seda asja, mis on sündinud, mis Issand on meile teada annud!"',
        16: 'Ja nad tulid tõtates ning leidsid Maarja ja Joosepi ja lapsukese, kes magas sõimes.',
        17: 'Aga kui nad seda nägid, teatasid nad asjast, mis neile oli üteldud selle lapsukese kohta.',
        18: 'Ja kõik, kes seda kuulsid, panid imeks, mida karjased neile rääkisid.',
        19: 'Ent Maarja pidas kõik need sõnad meeles ning mõtles nendele Oma südames.',
        20: 'Ja karjased läksid tagasi Jumalale au andes ja Teda kiites kõige eest, mis nad olid kuulnud ja näinud, nõnda nagu neile oli üteldud.',
        21: 'Ja kui kaheksa päeva täis sai ja Laps pidi ümber lõigatama, pandi Temale nimeks Jeesus, mille Ingel oli pannud, enne kui Laps sai Ema ihusse.',
        22: 'Ja kui nende puhastuspäevad täis said Moosese käsuõpetuse järele, viisid nad Lapse Jeruusalemma, et Teda seada Issanda ette -',
        23: 'nagu on kirjutatud Issanda käsuõpetuses: "Iga poeglaps, kes on ema esmasündinu, loetagu pühitsetuks Issandale"',
        24: '- ja tuua ohver, nagu Issanda käsuõpetuses on üteldud: paar turteltuvi või kaks muud tuvi.',
        25: 'Ja vaata, Jeruusalemas oli mees, Siimeon nimi. See mees oli õige ja jumalakartlik ning ootas Iisraeli troosti; ja Püha Vaim oli tema peal.',
        26: 'Temale oli Püha Vaim ilmutanud, et ta ei näe surma, enne kui ta on näinud Issanda Võitut.',
        27: 'Ja ta tuli Vaimu sunnil pühakotta. Ja kui vanemad Lapsukese Jeesuse sinna tõid, et Tema pärast teha käsuõpetuse kombe järele,',
        28: 'siis ta võttis Tema sülle, kiitis Jumalat ning ütles:',
        29: '"Issand, nüüd Sa lased Oma sulase rahus minna Oma sõna järele,',
        30: 'sest mu silmad on näinud Sinu päästet,',
        31: 'mille Sa oled valmistanud kõigi rahvaste nähes,',
        32: 'valguseks, mis peab ilmuma paganaile ja auhiilguseks Oma rahvale Iisraelile!"',
        33: 'Ja Ta isa ja Ema panid imeks, mida Temast räägiti.',
        34: 'Ja Siimeon õnnistas neid ja ütles Maarjale, Tema Emale: "Vaata, Seesinane on seatud langemiseks ja tõusmiseks paljudele Iisraelis ja tähiseks, mille vastu räägitakse -',
        35: 'ent Sinu Omastki hingest peab mõõk läbi tungima - et saaksid avalikuks paljude südamete mõtlemised!"',
        36: 'Ja seal oli naisprohvet Anna, Fanueli tütar, Aaseri suguharust. See oli väga elatanud ja oli elanud oma mehega seitse aastat pärast oma neitsipõlve,',
        37: 'ja tema oli lesk, ligi kaheksakümmend neli aastat vana. See ei läinud ära pühakojast, vaid teenis Jumalat paastumiste ja palvetamistega ööd ja päevad.',
        38: 'Tema tuli sinna samal tunnil ja ülistas Jumalat ning kõneles Temast kõikidele, kes ootasid Jeruusalema lunastust.',
        39: 'Ja kui nad olid lõpetanud kõik, mis tuli teha Issanda käsuõpetuse järele, läksid nad tagasi Galileamaale oma Naatsareti linna.',
        40: 'Aga Lapsuke kasvas ja sai tugevaks ning täitus tarkusega. Ja Jumala arm oli Tema peal.',
        41: 'Ja Tema vanemad käisid iga aasta Jeruusalemas paasapühil.',
        42: 'Ja kui Ta sai kaheteistkümneaastaseks, läksid nad üles Jeruusalemma pühadeaja kommet mööda.',
        43: 'Ja kui pärast nende päevade möödumist nad olid kodu poole minemas, jäi Laps Jeesus Jeruusalemma; ja Tema vanemad ei pannud seda tähele.',
        44: 'Nad arvasid Tema olevat kaasteekäijate seas, ja käisid ühe ühe päeva tee ning otsisid Teda sugulaste ja tuttavate juurest;',
        45: 'ja kui nad Teda ei leidnud, läksid nad tagasi Jeruusalemma ja otsisid Teda sealt.',
        46: 'Ja kolme päeva pärast sündis, et nad Ta leidsid pühakojas istumast õpetajate keskel ja neid kuulamast ja neilt küsimast.',
        47: 'Aga kõik, kes Teda kuulsid, panid imeks tema mõistust ja tema kostuseid.',
        48: 'Ja Teda nähes ehmusid Tema vanemad väga, ja Ta Ema ütles Temale: "Poeg, miks Sa oled meile nõnda teinud? Vaata, Su isa ja Mina oleme valuga Sind otsinud!"',
        49: 'siis Ta ütles neile: "Miks te Mind otsite? Eks te teadnud, et Ma pean olema selles, mis on Mu Isa Oma?"',
        50: 'Aga nemad ei mõistnud seda sõna, mis Ta neile rääkis.',
        51: 'Ja ta läks ühes nendega ja tuli Naatsaretti ja oli neile allaheitlik. Ja Tema Ema pidas kõik need sõnad Oma südames.',
        52: 'Ja Jeesus edenes tarkuses ja pikkuses ja armus Jumala ja inimeste juures.',
    },
    3: {
        1: 'Keiser Tibeeriuse valitsuse viieteistkümnendal aastal, kui Pontius Pilaatus oli Judea maavalitseja ja Heroodes Galilea nelivürst ja Filippus, tema vend, Iturea ja Trahhoniitisemaa nelivürst ja Lüsaanias Abileene nelivürst,',
        2: 'kui ülempreestreiks olid Annas ja Kaifas, sai Jumala sõna Sakariase poja Johannese kätte kõrves.',
        3: 'Ja ta tuli kogu Jordani ümberkaudsele maale ja kuulutas meeleparandusristimist pattude andekssaamiseks,',
        4: 'nagu on kirjutatud prohvet Jesaja sõnade raamatus: "Hüüdja hääl on kõrves: Valmistage Issanda teed, õgvendage tema teerajad!',
        5: 'Kõik kuristikud täidetagu ja kõik mäed ja mäekünkad tehtagu madalaks; mis on kõver, saagu sirgeks, ja mis on mätlik, siledaks teeks;',
        6: 'siis kõik liha näeb Jumala päästet!"',
        7: 'Siis ta ütles rahvale, kes tuli välja ennast laskma tema poolt ristida: "Te rästikute sigitis, kes on teile annud märku põgeneda tulevase viha eest?',
        8: 'Seepärast kandke õiget meeleparanduse vilja ja ärge hakake iseenestes ütlema: Meil on isaks Aabraham! Sest ma ütlen teile, et Jumal võib neist kividest äratada Aabrahamile lapsi!',
        9: 'Kuid kirves on ka juba puude juure küljes! Iga puu nüüd, mis head vilja ei kanna, raiutakse maha ja visatakse tulle!"',
        10: 'Ja rahvas küsis temalt ning ütles: "Mis meil siis tuleb teha?"',
        11: 'Tema vastas ning ütles neile: "Kellel on kaks vammust, see andku sellele, kellel ei ole, ja kellel on rooga, see tehku nõndasamuti!"',
        12: 'Ent ka tölnereid tuli endid laskma ristida, ja need ütlesid temale: "Õpetaja, mis meil tuleb teha?"',
        13: 'Aga ta ütles neile: "Ärge nõudke rohkem kui teile on seatud!"',
        14: 'Ka küsisid temalt sõjamehed ning ütlesid: "Ja meie, mis siis meil tuleb teha?" Ja ta ütles neile: "Ärge tehke kellelegi liiga ja ärge survake kedagi, vaid olge rahul oma palgaga!"',
        15: 'Aga kui rahvas ootas ja kõik oma südames mõtlesid Johannesest, kas tema vahest ei ole Kristus,',
        16: 'siis kostis Johannes ja ütles kõikidele: "Mina ristin teid veega; aga on tulemas Vägevam minust, Kelle jalatsite paela ma ei ole kõlvuline lahti päästma; Tema ristib teid Püha Vaimu ja tulega!',
        17: 'Tema visklabidas on Ta käes, et teha puhtaks Oma rehealune ja koguda nisud Oma aita, aga aganad põletada ära kustutamatu tulega!"',
        18: 'Ka veel muude asjade pärast manitsedes kuulutas ta armuõpetust rahvale.',
        19: 'Aga kui nelivürst Heroodes sai talt noomida Heroodiase, oma venna Filippuse naise pärast ja kõigi pahategude pärast, mis Heroodes oli teinud,',
        20: 'sai ta peale kõige muu veel toime sellega, et ta Johannese pani kinni vanglasse.',
        21: 'Ent sündis, kui kõike rahvast ristiti ja ka Jeesus oli ristitud ja palvetas, et taevas avati',
        22: 'ja Püha Vaim tuli ihulikul kujul alla nagu tuvi Tema peale, ja hääl kostis taevast: "Sina oled Mu armas Poeg, Sinust on Mul hea meel!"',
        23: 'Ja Jeesus oli Oma tegevust alates umbes kolmkümmend aastat vana ja oli, nagu arvati, Joosepi Poeg, kes oli Eeli poeg.',
        24: 'Eeli oli Mattati, see oli Leevi, see oli Melki, see oli Jannai, see oli Joosepi,',
        25: 'see oli Matatia, see oli Aamose, see oli Nahumi, see oli Esli, see oli Nangai,',
        26: 'see oli Mahati, see oli Matatia, see oli Simei, see oli Jooseki, see oli Jooda,',
        27: 'see oli Joohanani, see oli Reesa, see oli Serubaabeli, see oli Sealtieli, see oli Neeri,',
        28: 'see oli Melki, see oli Adi, see oli Koosami, see oli Elmadami, see oli Eeri,',
        29: 'see oli Jeesuse, see oli Elieseri, see oli Joorimi, see oli Mattati, see oli Leevi,',
        30: 'see oli Siimeoni, see oli Juuda, see oli Joosepi, see oli Joonami, see oli Eljakimi,',
        31: 'see oli Melea, see oli Menna, see oli Matata, see oli Naatani, see oli Taaveti,',
        32: 'see oli Jesse, see oli Oobedi, see oli Boase, see oli Salma, see oli Nahsoni,',
        33: 'see oli Amminaadabi, see oli Admini, see oli Arni, see oli Hesromi, see oli Peretsi, see oli Juuda,',
        34: 'see oli Jaakobi, see oli Iisaki, see oli Aabrahami, see oli Taara, see oli Naahori,',
        35: 'see oli Serugi, see oli Reu, see oli Pelegi, see oli Eeberi, see oli Sela,',
        36: 'see oli Keenani, see oli Arpaksadi, see oli Seemi, see oli Noa, see oli Lenseki,',
        37: 'see oli Metuusala, see oli Eenoki, see oli Jeredi, see oli Mahalaleli, see oli Keenani,',
        38: 'see oli Eenose, see oli Seti, see oli Aadama, see oli Jumala poeg.',
    },
    4: {
        1: 'Siis tuli Jeesus, täis Püha Vaimu, tagasi Jordani äärest, ja Ta aeti Vaimu läbi kõrbe;',
        2: 'ja nelikümmend päeva kurat kiusas Teda. Ja Ta ei söönud midagi neil päevil. Ja kui need möödusid, tuli Temale nälg.',
        3: 'Siis ütles kurat Temale: "Kui Sa oled Jumala Poeg, siis ütle sellele kivile, et ta leivaks muutuks!"',
        4: 'Jeesus vastas temale: "Kirjutatud on, et inimene ei ela ükspäinis leivast!"',
        5: 'Siis kurat viis Tema kõrgele ning näitas Talle kõik maailma kuningriigid viivu ajaga.',
        6: 'Ja kurat ütles Temale: "Ma annan Sulle meelevalla kõigi nende üle ja nende auhiilguse, sest see on antud minule ja mina annan selle, kellele ma iganes tahan.',
        7: 'Kui Sa nüüd kummardad minu ette, on kõik Sinu!"',
        8: 'Jeesus vastas ning ütles temale: "Kirjutatud on: Sina pead Issandat, oma Jumalat kummardama ja ükspäinis Teda teenima!"',
        9: 'Ja ta viis Tema Jeruusalemma ja asetas ta pühakoja harjale ning ütles Talle: "Kui Sa oled Jumala Poeg, siis kukuta Ennast siit alla;',
        10: 'sest on kirjutatud: Ta annab Oma Inglitele käsu Sinu pärast, et nad Sind hoiaksid',
        11: 'ja et nad Sind kätel kannaksid, et Sa Oma jalga vastu kivi ei tõukaks!"',
        12: 'Jeesus vastas ning ütles temale: "Üteldud on: Sa ei tohi Issandat, oma Jumalat kiusata!"',
        13: 'Ja kui kurat kõik kiusamise oli lõpetanud, läks ta Temast eemale mõneks ajaks.',
        14: 'Ja Jeesus läks tagasi Vaimu väes Galileasse; ja kuuldus Temast levis kogu ümberkaudsele maale.',
        15: 'Ja Ta õpetas nende kogudusekodades, ja kõik andsid Temale au.',
        16: 'üles lugema.',
        17: 'Ja Tema kätte anti prohvet Jesaja raamat. Ja kui Ta raamatu avas, leidis Ta koha, kuhu oli kirjutatud:',
        18: '"Issanda Vaim on Minu peal; seepärast on Ta Mind võidnud kuulutama Evangeeliumi vaestele; Ta on Mind läkitanud kuulutama vabakssaamist seotuile ja nägemist pimedaile, laskma rõhutuid vabadusse,',
        19: 'kuulutama Issanda meelepärast aastat!"',
        20: 'Ja kui Ta raamatu oli kokku keeranud, andis Ta selle kojasulase kätte ja istus maha; ja kõikide silmad kogudusekojas olid sihitud Tema peale.',
        21: 'Ta hakkas neile kõnelema: "Täna on see kiri täide läinud teie kuuldes!"',
        22: 'Ja kõik tunnustasid Teda ja panid imeks neid armu sõnu, mis lähtusid Ta suust, ning ütlesid: "Eks Seesinane ole Joosepi poeg?"',
        23: 'Siis Ta ütles neile: "Küllap te Mulle ütlete selle vanasõna: Arst, aita Iseennast! Neid suuri asju, mida me oleme kuulnud Kapernaumas sündinud olevat, tee ka siin Oma kodukohas!"',
        24: 'Aga Ta ütles: "Tõesti Ma ütlen teile, ükski prohvet ei ole meelepärane oma kodumaal.',
        25: 'Tõepoolest Ma ütlen teile: Palju lesknaisi oli Iisraelis Eelija ajal, mil taevas oli kinni pandud kolm aastat ja kuus kuud, kui suur nälg tuli üle kogu maa;',
        26: 'aga ei ühegi juure nende seast ei läkitatud Eelijat kui vaid Sareptasse Siidonimaale lesknaise juure.',
        27: 'Ja palju pidalitõbiseid oli Iisraelis prohvet Eliisa ajal, aga ükski neist ei saanud puhtaks kui vaid Naaman, see süürlane!"',
        28: 'Seda kuuldes said kõik kogudusekojas täis viha,',
        29: 'ja tõusid ning tõukasid Tema linnast välja ja viisid Ta üles mäerünkale, millele nende linn oli ehitatud, et Teda kukutada ülepeakaela alla.',
        30: 'Aga Tema sammus nende keskelt läbi ja läks Oma teed.',
        31: 'Ja Ta tuli Kapernauma, Galilea linna, ja õpetas neid hingamispäevil.',
        32: 'Ja nemad hämmastusid Tema õpetusest, sest Ta sõnal oli meelevald.',
        33: 'Ja kogudusekojas oli mees, kellel oli rüveda pahareti vaim, see kisendas suure häälega:',
        34: '"Oeh, mis on meil Sinuga tegemist, Jeesus Naatsaretlane? Oled Sa tulnud meid hävitama? Ma tunnen Sind, kes Sa oled, Jumala Püha!"',
        35: 'Siis Jeesus sõitles teda ning ütles: "Ole vait ja mine temast välja!" Ja kuri vaim viskas ta maha nende keskele ja väljus temast ega teinud talle ühtki kahju.',
        36: 'Ja kohkumine valdas kõiki, ja nad rääkisid isekeskis ning ütlesid: "Mis lugu see on, et Ta meelevalla ja väega käsib rüvedaid vaime, ja need väljuvad?"',
        37: 'Ja kuuldus Temast levis kõigisse ümberkaudse maa paikadesse.',
        38: 'Aga ta tõusis üles kogudusekojast ja läks Siimona kotta. Ja Siimona ämm oli haige raskes palavikus, ja nad palusid Teda tema pärast.',
        39: 'Ja Ta astus tema juure ja ähvardas palavikku, ja see lahkus temast. Ja sedamaid tõusis naine üles ja ümmardas neid.',
        40: 'Aga kui päike looja läks, tõid kõik, kelledel oli haigeid mõnesugustes tõbedes, need Tema juure, ja Ta pani igaühe peale Oma käed ning tegi nad terveks.',
        41: 'Aga ka kurjad vaimud läksid paljudest välja kisendades ning üteldes: "Sina oled Jumala Poeg!" Ja Tema sõitles neid ega lubanud neid rääkida, sest et nad teadsid Tema olevat Kristuse.',
        42: 'Ja päeva tulles väljus Ta ja läks tühja paika; kuid rahvahulgad otsisid Teda ning tulid Tema juure. Ja nad pidasid Teda kinni, et Ta ei läheks ära nende juurest.',
        43: 'Aga Tema ütles neile: "Ma pean ka muudele linnadele kuulutama Jumala Riigi Evangeeliumi, sest selleks Ma olen läkitatud!"',
        44: 'Ja Ta jutlustas Galilea kogudusekodades.',
    },
    5: {
        1: 'Aga sündis, kui rahvas tema juure tungis Jumala sõna kuulama ja Ta seisis Gennesareti järve ääres,',
        2: 'et Ta nägi kaht paati järve rannas seisvat; aga kalamehed olid neist väljunud ja loputasid võrke.',
        3: 'Tema astus ühte paati, mis oli Siimona oma, ja palus teda natuke maad rannast eemale sõuda. Siis Ta istus maha ja õpetas rahvast paadist.',
        4: 'Aga kui Ta lakkas kõnelemast, ütles Ta Siimonale: "Sõua sügavale kohale ja heitke oma võrgud välja loomuse katseks!"',
        5: 'Siimon vastas ning ütles Temale: "Õpetaja, me oleme kogu öö rühelnud ega ole ühtki saanud, aga Sinu sõna peale ma heidan võrgud välja!"',
        6: 'Ja kui nad seda tegid, said nad suure hulga kalu; ja nende võrgud rebenesid.',
        7: 'Ja nad viipasid oma kaaslastele teises paadis, et nad tuleksid ja neid aitaksid. Ja nad tulid ja täitsid mõlemad paadid nõnda, et need olid vajumas.',
        8: 'Seda nähes heitis Siimon Peetrus maha Jeesuse põlvede ette ning ütles: "Issand, mine minu juurest ära, sest ma olen patune inimene!"',
        9: 'Sest kohkumine oli vallanud teda ja kõiki, kes temaga olid, kalasaagi pärast, mis nad olid saanud;',
        10: 'nõndasamuti ka Jakoobust ja Johannest, Sebedeuse poegi, kes olid Siimona kaaslased. Ja Jeesus ütles Siimonale: "Ära karda, nüüdsest alates pead sa inimesi püüdma!"',
        11: 'Ja nad vedasid paadid maale ja jätsid kõik maha ja järgisid Teda.',
        12: 'Ja kui Ta viibis ühes linnas, vaata, siis oli seal mees täis pidalitõbe. Kui ta Jeesust nägi, heitis ta silmili maha, palus Teda ning ütles: "Issand, kui Sa tahad, võid Sa mind puhtaks teha!"',
        13: 'Ja Ta sirutas oma käe ja puudutas teda ning ütles: "Ma tahan, saa puhtaks!" Ja sedamaid lahkus pidalitõbi temast.',
        14: 'Ja Tema keelas teda seda kellelegi ütlemast "Mine vaid" - ütles Ta - "ja näita ennast preestrile ja ohverda oma puhastuse eest, nõnda nagu Mooses on seadnud neile tunnistuseks!"',
        15: 'Aga sõnum temast levis laiemale, ja palju rahvast tuli kokku teda kuulama ja temalt tervist saama tõbedest.',
        16: 'Aga Tema läks kõrvale tühjadesse paikadesse ja palvetas seal.',
        17: 'Ja ühel päeval, kui Ta õpetas, oli seal istumas varisere ja käsutundjaid, kes olid tulnud kõigist Galilea ja Judea küladest ja Jeruusalemast; ja Issanda vägi oli seal selleks, et Jeesus terveks teeks.',
        18: 'Ja vaata, mehed tõid voodiga inimese, kes oli halvatud; ja nad püüdsid teda sisse viia ja Tema ette panna.',
        19: 'Ja kui nad rahva pärast ei leidnud, kust nad ta oleksid saanud sisse viia, läksid nad üles katusele ja lasksid ta katuse kivide vahelt alla kõige voodiga otse Jeesuse ette maha.',
        20: 'Kui Tema nende usku nägi, ütles Ta: "Inimene, sinu patud on sulle andeks antud!"',
        21: 'Siis kirjatundjad ja variserid hakkasid mõtlema ning ütlesid: "Kes see on, kes nõnda Jumalat pilgates räägib? Kes muu võib patte andeks anda kui üksnes Jumal?"',
        22: 'Aga Jeesus tundis ära nende mõtlemised ja kostust andes Ta ütles neile: "Mida te mõtlete oma südames?',
        23: 'Kumb on hõlpsam ütelda: Su patud on sulle andeks antud, või ütelda: Tõuse üles ja kõnni?',
        24: 'Aga et te teaksite, et Inimese Pojal on meelevald patte andeks anda," - siis ütles Ta halvatule: "Ma ütlen sulle, tõuse üles ja võta oma voodi ning mine koju!"',
        25: 'Ja sedamaid tõusis ta nende nähes üles, võttis oma voodi, millel ta oli lamanud, ja läks koju Jumalale au andes.',
        26: 'Ja hämmastus valdas kõiki, ja nad andsid Jumalale au ja said täis kartust ning ütlesid: "Me oleme täna näinud imelisi asju!"',
        27: 'Pärast seda Ta läks välja ja nägi tölnerit, Leevi nimi, tollihoones istuvat ja ütles temale: "Järgi Mind!"',
        28: 'Ja ta jättis kõik maha, tõusis ja järgis Teda.',
        29: 'Ja Leevi tegi Temale suure võõruspidu oma majas, ja suur hulk tölnereid ja teisi oli ühes nendega lauas istumas.',
        30: 'Siis variserid ja nende kirjatundjad nurisesid tema jüngrite vastu ning ütlesid: "Miks te sööte ja joote ühes tölnerite ja patustega?"',
        31: 'Ja Jeesus vastas neile ning ütles: "Ei ole arsti vaja tervetele, ainult haigetele!',
        32: 'Ma ei ole tulnud õigeid kutsuma meeleparandusele, vaid patuseid!"',
        33: 'Aga nemad ütlesid Temale: "Johannese jüngrid paastuvad sagedasti ja peavad palveid, samuti variseridegi omad, aga Sinu jüngrid söövad ja joovad!"',
        34: 'Jeesus ütles neile: "Kas te võite peiupoisse panna paastuma sel ajal, kui peigmees on nende juures?',
        35: 'Ent päevad tulevad, mil peigmees võetakse neilt ära; siis nad paastuvad neil päevil!"',
        36: 'Aga Ta ütles neile ka tähendamissõna: "Ükski ei lõika paika uue kuue küljest ega pane seda vana kuue peale, muidu ta lõikab katki ka uue kuue, ja pealegi ei sobi vanale kuuele paik uue küljest.',
        37: 'Ka ei pane keegi värsket viina vanusse nahklähkreisse, muidu värske viin ratkub lähkrid ja ta jookseb maha ning lähkrid lähevad rikki; 38 vaid värske viin tuleb panna uutesse nahklähkritesse,',
        39: 'siis keegi, kes joob vana, ei himusta värsket, vaid ütleb: Vana on maitsev!"',
    },
    6: {
        1: 'Ja hingamispäeval Ta juhtus minema läbi viljapõldude; ja Tema jüngrid katkusid päid, hõõrusid neid käte vahel ja sõid.',
        2: 'Ent mõningad variseridest ütlesid: "Miks te teete seda, mida hingamispäeval ei ole luba teha?"',
        3: 'Aga Jeesus vastas ning ütles neile: "Eks te ole seda lugenud, mida Taavet tegi, kui temal ja ta kaaslastel oli nälg,',
        4: 'kuidas ta läks Jumala kotta ja võttis vaateleivad, sõi ning andis ka oma kaaslasile, ehk küll neid ei olnud luba süüa muil kui üksnes preestritel!"',
        5: 'Ja Ta ütles neile: "Inimese Poeg on hingamispäeva isand!"',
        6: 'Aga juhtus ühel teisel hingamispäeval, et ta läks kogudusekotta ja õpetas. Ja seal oli inimene, kelle parem käsi oli kuivanud.',
        7: 'Aga kirjatundjad ja variserid varitsesid Teda, kas Ta hingamispäeval peaks terveks tegema, et nad leiaksid kaebust Tema peale.',
        8: 'Tema aga teadis nende mõtted ja ütles mehele, kellel oli kuivanud käsi: "Tõuse üles ja astu keskele!" Ja ta tõusis ja seisis seal.',
        9: 'Siis ütles Jeesus neile: "Ma küsin teilt: Kas hingamispäeval on luba teha head või kurja, hinge päästa või hukka saata?"',
        10: 'Ja Ta vaatas ümber nende kõikide peale ja ütles mehele: "Siruta oma käsi!" Ja see tegi nõnda. Ja tema käsi sai jälle terveks.',
        11: 'Nemad aga sattusid meeletumasse vimma ja rääkisid üksteisega sellest, mida nad küll võiksid teha Jeesusele.',
        12: 'Neil päevil sündis ka, et Ta läks välja mäele palvetama ja viibis kogu öö Jumala palumises.',
        13: 'Ja kui valgeks läks, kutsus Ta Oma jüngrid Enese juure ja valis nende seast kaksteistkümmend, kelled Ta nimetas ka apostliteks:',
        14: 'Siimona, keda Ta nimetas ka Peetruseks, ja tema venna Andrease, Jakoobuse ja Johannese, Filippuse ja Bartolomeuse,',
        15: 'Matteuse ja Tooma, Jakoobuse, Alfeuse poja, ja Siimona, keda hüütakse Selooteseks,',
        16: 'ja Juuda, Jakoobuse poja, ja Juudas Iskarioti, kes sai äraandjaks.',
        17: 'Nendega Ta astus alla ja jäi peatuma lagedale paigale; ja seal oli suur hulk Tema jüngreid ja kogu Juudamaalt ja Jeruusalemast ning Tüürose ja Siidoni rannamaalt suur rahvakogu,',
        18: 'kes oli tulnud Teda kuulama ja ennast laskma parandada oma haigustest. Ja ka need, keda rüvedad vaimud vaevasid, said terveks.',
        19: 'Ja kõik rahvas püüdis Teda puudutada, sest vägi lähtus Temast ja parandas kõik.',
        20: 'Ja Tema tõstis silmad Oma jüngrite poole ja ütles: "Õndsad olete, vaesed, sest teie päralt on Jumala Riik.',
        21: 'Õndsad teie, kelledel nüüd on nälg, sest teid peab toidetama. Õndsad teie, kes nüüd nutate, sest siis te naerate.',
        22: 'Õndsad olete, kui inimesed teid vihkavad ja kui nad teid kogudusest välja heidavad ning laimavad ja teie nime kui paha nime hülgavad Inimese Poja pärast.',
        23: 'Rõõmutsege sel päeval ja hüpake, sest vaata, teie paik on suur taevas! Tegid ju nõndasamuti prohvetitega nende isad.',
        24: 'Kuid häda teile rikastele! Sest teil on troost käes.',
        25: 'Häda teile, kes nüüd olete täidetud, sest teile tuleb nälg! Häda teile, kes nüüd naerate, sest te saate veel leinata ja nutta!',
        26: 'Häda teile, kui kõik inimesed teist räägivad head, sest nõndasamuti tegid nende isad valeprohvetitele!',
        27: 'Aga teile, kes kuulete, ütlen Ma: Armastage oma vaenlasi, tehke head neile, kes teid vihkavad;',
        28: 'õnnistage neid, kes teid neavad; paluge nende eest, kes teid siunavad.',
        29: 'Kes sind lööb vastu kõrva, sellele paku ka teine; ja kes sult võtab kuue, sellele ära keela vammust.',
        30: 'Anna igaühele, kes sind palub, ja sellelt, kes võtab sinu oma, ära nõua tagasi.',
        31: 'Ja nõnda nagu te tahate, et inimesed teile teeksid, nõnda tehke neile.',
        32: 'Ja kui te armastate neid, kes teid armastavad, mis tänu on teil sellest? Sest patusedki armastavad neid, kes neid armastavad.',
        33: 'Ja kui te teete head oma heategijaile, mis tänu on teil sellest? Sest patusedki teevad sedasama.',
        34: 'Ja kui te laenate neile, kelledelt te loodate tagasi saada, mis tänu on teil sellest? Patusedki laenavad patustele, et nad samavõrra saaksid tagasi.',
        35: 'Aga armastage oma vihamehi ja tehke head ja laenake ilma midagi selle vastu lootmata; siis teie palk on suur ja te olete Kõigekõrgema lapsed, sest Tema on lahke ka tänamatute ja kurjade vastu.',
        36: 'Olge armulised, nõnda nagu teie Isa on armuline.',
        37: 'Ja ärge mõistke kohut, siis ei mõisteta ka teie üle kohut. Ärge mõistke hukka, siis ei mõisteta ka teid hukka. Andke andeks, siis antakse ka teile andeks.',
        38: 'Andke, siis antakse ka teile; hea, tuubitud ja raputatud ja kuhjaga mõõt antakse teie rüppe; sest sama mõõduga, millega teie mõõdate, mõõdetakse ka teile."',
        39: 'Aga Ta ütles neile võrdumi: "Egas pime või pimedat talutada? Eks nad mõlemad kuku auku?',
        40: 'Ei ole õpilane ülem oma õpetajast, ent iga täiesti õpetatu on samasugune kui ta õpetaja.',
        41: 'Aga miks sa näed pindu oma venna silmas, kuid palki su omas silmas sa ei pane tähele?',
        42: 'Ehk kuidas sa võid ütelda oma vennale: Vend, lase ma tõmban pinnu sinu silmast! ja sa ise ei näe palki omas silmas? Sa silmakirjatseja! Tõmba esmalt palk omast silmast ja siis sa seletad pindu välja tõmmata oma venna silmast!',
        43: 'Sest ei ole head puud, mis kannaks halba vilja, ega jälle halba puud, mis kannaks head vilja.',
        44: 'Sest igat puud tuntakse tema viljast. Ei nopita ju viigimarju kibuvitsust ega korjata viinakobaraid ohakaist.',
        45: 'Hea inimene toob esile head oma südame heast tagavarast ja halb inimene toob esile halba oma südame halvast tagavarast. Sest mida süda täis, sellest suu räägib!',
        46: 'Aga miks te Mind hüüate: Issand, Issand! ega tee, mida Ma ütlen?',
        47: 'Igaüks, kes tuleb Minu juure ja kuuleb Mu sõnu ning teeb nende järele - Ma näitan teile, kelle sarnane ta on.',
        48: 'Ta on inimese sarnane, kes maja ehitades kaevas ja võttis sügavasse ning rajas tema aluse kaljule. Kui siis suurvesi tuli, murdus vool vastu seda maja ja ei suutnud seda kõigutada, sest see oli hästi ehitatud.',
        49: 'Aga kes kuuleb ega tee, see on inimese sarnane, kes maja rajas maa peale ilma aluseta; ja voolav vesi rõhus selle vastu ja see langes kohe kokku; ja selle maja varisemine oli suur!"',
    },
    7: {
        1: 'Kui Ta kõik Oma kõned oli lõpetanud kuulavale rahvale, läks Ta Kapernauma.',
        2: 'Ja ühe sõjapealiku sulane oli haige ning suremisel; ja ta oli kallis tema meelest.',
        3: 'Aga kui ta Jeesusest kuulis, läkitas ta juutide vanemad Tema juure ja palus Teda, et Ta tuleks ja teeks tema sulase terveks.',
        4: 'Kui need saabusid Jeesuse juure, palusid nad Teda üliväga ning ütlesid: "Ta on seda väärt, et Sa temale seda teed;',
        5: 'sest ta armastab meie rahvast ja tema on meile ehitanud kogudusekoja."',
        6: 'Jeesus läks nendega. Aga kui ta enam ei olnud majast kaugel, läkitas pealik oma sõbrad Talle ütlema: "Issand, ära tee Enesele vaeva, sest mina ei ole väärt, et Sina mu katuse alla tuled.',
        7: 'Sellepärast ei ole mina ennast arvanud väärt tulema Sinu juure, vaid ütle aga sõna, siis mu sulane paraneb.',
        8: 'Sest minagi olen inimene, kes on pandud valitsuse alla, ja minu all on sõjamehi, ja kui ma ütlen ühele: Mine! siis ta läheb, ja teisele: Tule! siis ta tuleb, ja oma sulasele: Tee seda! siis ta teeb."',
        9: 'Kui Jeesus seda kuulis imetles Ta teda ja pöördudes rahva poole, kes järel käis, ütles Ta: "Ma ütlen teile, ei ole ma Iisraelistki leidnud nii suurt usku!"',
        10: 'Ja kui need, kes olid läkitatud, jälle koju said, leidsid nad sulase terve olevat.',
        11: 'Järgmisel päeval läks Ta linna, mida hüütakse Nainiks, ja Temaga ühes läksid Tema jüngrid ja palju rahvast.',
        12: 'Kui Ta linna värava ligi jõudis, vaata, siis kanti välja surnut, oma ema ainust poega; ja ema oli lesk. Ja suur hulk linna rahvast oli temaga.',
        13: 'Ja kui Issand teda nägi, oli tal väga hale meel temast ja ütles talle: "Ära nuta!"',
        14: 'Ja ta astus ligi ja puudutas puusärki; aga kandjad jäid seisma. Ja Ta ütles: "Noormees, ma ütlen sulle, tõuse üles!"',
        15: 'Ja surnu tõusis istukile ja hakkas rääkima. Ja Ta andis tema ta emale.',
        16: 'Aga neid kõiki valdas hirm, ja nad andsid au Jumalale ning ütlesid: "Suur prohvet on meie seas tõusnud ja Jumal on tulnud Oma rahvast katsuma!"',
        17: 'Ja see jutt Temast levis kogu Juudamaale ja kõigisse ümberkaudseisse paikadesse.',
        18: 'Ja seda kõike kuulutasid Johannesele tema jüngrid. Ja Johannes kutsus enese juure kaks oma jüngritest',
        19: 'ja läkitas nad Issanda juure küsima: "Kas oled Sina See, Kes tuleb, või peame ootama teist?"',
        20: 'Aga kui mehed Tema juure jõudsid, ütlesid nad: "Ristija Johannes läkitas meid Sinu juure küsima: Kas oled Sina See, Kes tuleb, või peame ootama teist?"',
        21: 'Ent samal tunnil Ta tegi paljud terveks tõbedest ja valudest ja kurjest vaimudest, ja paljudele pimedaile Ta kinkis nägemise.',
        22: 'Ja Ta vastas ning ütles neile: "Minge ja kuulutage Johannesele, mida te olete näinud ja kuulnud: pimedad näevad jälle, jalutumad käivad, pidalitõbised saavad puhtaks, kurdid kuulevad, surnud äratatakse üles, vaestele kuulutatakse Evangeeliumi;',
        23: 'ja õnnis on see, kes Minust ei pahandu!"',
        24: 'Aga kui Johannese käskjalad olid ära läinud, hakkas Ta rahvale rääkima Johannesest: "Mida te olete läinud välja kõrbe vaatama? Pilliroogu, mida tuul kõigutab?',
        25: 'Või mida te olete välja läinud vaatama? Inimest, pehmete riietega riietatud? Vaata, kes käivad toredas riietuses ja endid hellitavad, need on kuninglikes kodades!',
        26: 'Või mida te olete välja läinud vaatama? Kas prohvetit? Tõesti, Ma ütlen teile, ta on veel rohkem kui prohvet!',
        27: 'Tema on see, kellest on kirjutatud: Vaata, Mina läkitan Sinu palge eele Oma Ingli, kes Sulle tee valmistab Sinu ees!',
        28: 'Mina ütlen teile, ei ole kedagi suuremat naisest sündinute seas kui Johannes, aga väikseim Jumala Riigis on suurem temast!"',
        29: 'Ja kõik rahvas, kes seda kuulis, ja tölnerid tunnistasid Jumala õigeks, lastes endid ristida Johannese ristimisega.',
        30: 'Variserid ja käsutundjad aga tegid tühjaks Jumala tahte eneste kohta ega lasknud teda endid ristida.',
        31: '"Kellega Ma siis võrdlen selle sugupõlve inimesi ja kelle sarnased nad on?',
        32: 'Nad on laste sarnased, kes turul istuvad ja üksteisele hüüavad nõnda: Me oleme teile vilet ajanud, ja te ei ole tantsinud; me oleme teile nutulaulu laulnud, ja te ei ole nutnud!',
        33: 'Sest Ristija Johannes on tulnud, ja ta ei söönud leiba ega joonud viina; ja te ütlete: Temal on kuri vaim!',
        34: 'Inimese Poeg on tulnud, ja ta sööb ja joob, ja te ütlete: Vaata, see inimene on söödik ja viinajoodik, tölnerite ja patuste sõber!',
        35: 'Ometi mõistetakse tarkus õigeks kõigi tema laste poolt!"',
        36: 'Aga keegi variseridest palus Teda enesega leiba võtma. Ja Ta läks variseri kotta ja istus lauda.',
        37: 'Ja vaata, selles linnas oli naine, kes oli patune. Kui see teada sai, et Ta istub lauas variseri kojas, tõi ta alabasterriistatäie kallist lõhnasalvi',
        38: 'ja astus nuttes Tema taha ta jalgade juure ja hakkas Tema jalgu kastma silmaveega ja kuivatas neid oma juustega, ja suudles Tema jalgu ning võidis neid salviga.',
        39: 'Aga kui variser, kes Teda oli kutsunud, seda nägi, mõtles ta iseeneses nõnda: Kui Seesinane oleks prohvet, küll Ta siis ära tunneks, kes ja missugune see naine on, kes Teda puudutab, et ta on patune.',
        40: 'Ja Jeesus vastas ning ütles temale: "Siimon, mul on sulle midagi ütelda!" Aga tema kostis: "Õpetaja, räägi!"',
        41: '"Ühel rahalaenajal oli kaks võlglast: üks oli võlgu viissada teenarit, teine viiskümmend.',
        42: 'Aga kui neil ei olnud maksta, kinkis ta mõlemaile selle. Kumb neist nüüd teda rohkem armastab?"',
        43: 'Siimon vastas ning ütles: "Ma arvan see, kellele ta rohkem kinkis." Tema ütles temale: "Sa otsustasid õieti!"',
        44: 'Ja pöördudes naise poole, ütles Ta Siimonale: "Kas sa näed seda naist? Ma tulin sinu majasse, sa ei annud vett Mu jalgade tarvis, tema aga on pisaratega Mu jalgu kastnud ja oma juustega kuivatanud.',
        45: 'Sa ei annud Mulle suud; tema aga ei ole sellest ajast, kui ta sisse tuli, lakanud Minu jalgadele suud andmast.',
        46: 'Sa ei võidnud Mu pead õliga, tema aga on Mu jalgu võidnud salviga.',
        47: 'Sellepärast, ütlen Ma sulle, on tema rohked patud andeks antud, sest ta on palju armastanud. Aga kellele pisut andeks antakse, see armastab pisut!"',
        48: 'Ja Ta ütles naisele: "Sinu patud on sulle andeks antud!"',
        49: 'Siis need, kes Temaga lauas istusid, hakkasid iseeneses mõtlema: Kes see on, kes ka patud andeks annab?',
        50: 'Aga Tema ütles naisele: "Sinu usk on sind aidanud; mine rahuga!"',
    },
    8: {
        1: 'Pärast seda aega rändas Tema linnast linna ja külast külla ning jutlustas ja kuulutas Evangeeliumi Jumala Riigist. Ja need kaksteistkümmend olid Temaga,',
        2: 'ja mõned naised, kelled Tema oli terveks teinud kurjadest vaimudest ja tõbedest: Maarja, keda hüütakse Magdaleenaks, kellest seitse kurja vaimu oli välja läinud,',
        3: 'ja Johanna, Heroodese varahoidja Kuusa naine, ja Susanna ja palju muid, kes Teda toetasid oma varaga.',
        4: 'Aga kui palju rahvast kogunes ja kõigist linnadest tuli Tema juure, rääkis Ta tähendamissõnaga:',
        5: '"Külvaja läks välja oma seemet külvama. Ja kui ta külvas, kukkus muist tee ääre ja tallati ära, ja taeva linnud sõid selle ära.',
        6: 'Ja muist kukkus kaljule. Ja kui see tärkas, kuivas see ära, sest sellel ei olnud niiskust.',
        7: 'Ja muist kukkus ohakate keskele, ja ohakad kasvasid ühtlasi üles ja lämmatasid selle.',
        8: 'Ja muist kukkus heale maale, ja kui see tärkas, kandis see sajakordse vilja." Seda üteldes Ta hüüdis: "Kellel kõrvad on kuulda, see kuulgu!"',
        9: 'Siis küsisid Tema jüngrid Temalt, mida see tähendamissõna tähendab.',
        10: 'Tema ütles: "Teile on antud mõista Jumala Riigi Saladusi, aga muile tähendamissõnades, et nad nähes ei näeks ja kuuldes ei mõistaks.',
        11: 'Ent tähendamissõna on see: Seeme on Jumala sõna.',
        12: 'Teeäärsed on need, kes kuulevad; pärast tuleb kurat ja võtab sõna ära nende südamest, et nad ei usuks ega saaks õndsaks.',
        13: 'Kaljupealsed on need, kes kuuldes sõna rõõmuga vastu võtavad, kuid neil ei ole juurt; ajutiseks nad usuvad ja kiusatuse ajal nad loobuvad.',
        14: 'Mis ohakate sekka kukkus, need on need, kes kuulevad ja lähevad ära ning lämbuvad muredest ja rikkusest ja elu lõbudest ega kanna valmis vilja.',
        15: 'Aga mis on heas maas, on need, kes sõna kuulevad, kaunis ja heas südames peavad ning kannavad vilja kannatlikkuses.',
        16: 'Ükski, kes süütab küünla, ei kata seda astjaga kinni ega pane voodi alla, vaid asetab selle küünlajalale, et sissetulijad näeksid valgust.',
        17: 'Sest midagi ei ole varjul, mis ei saaks avalikuks, ei ole ka midagi salajas, mis ei saaks teatavaks ega tuleks ilmsiks.',
        18: 'Katsuge siis, kuidas te kuulete; sest kellel iganes on, sellele antakse, ja kellel iganes ei ole, sellelt võetakse seegi, mis ta arvab enesel olevat."',
        19: 'Aga Tema juure tulid Ta ema ja vennad ega võinud saada Tema ligi rahva pärast.',
        20: 'Ja Temale teatati: "Sinu Ema ja Su vennad seisavad õues ja tahavad Sind näha!"',
        21: 'Aga Ta kostis ning ütles neile: "Minu Ema ja Mu vennad on need, kes Jumala sõna kuulevad ja teevad selle järele!"',
        22: 'Ja ühel päeval astusid Tema ja Ta jüngrid paati, ja Ta ütles neile: "Lähme teisele poole järve!" Ja nad sõudsid minema.',
        23: 'Ja kui nad paadiga purjetasid, uinus Ta magama. Siis tõusis järvel tuulispea ja paat uhtus vett täis, ja nad olid hädas.',
        24: 'Siis nad tulid Tema juure, äratasid Ta üles ja ütlesid: "Õpetaja, õpetaja, me hukkume!" Aga Tema tõusis üles, ähvardas tuult ning vee lainetust, ja need raugesid ning ilm muutus vaikseks.',
        25: 'Aga Tema ütles neile: "Kus on teie usk?" Ent nad kartsid ja imestasid ning ütlesid üksteisele: "Kes see õieti on, et Tema käsib tuuli ja vett, ja need kuulevad Ta sõna?"',
        26: 'Ja nad purjetasid gerasalaste maale, mis on Galilea vastas.',
        27: 'Aga kui Tema astus maale, tuli linnast Talle vastu mees, kelle sees oli kurje vaime; ja ta ei olnud ammust ajast kuube selga pannud ega asunud majas, vaid surnuhaudades.',
        28: 'Kõige Kõrgema Jumala Poeg? Ma palun Sind, ära piina mind!"',
        29: "Sest Ta käskis rüvedat vaimu väljuda inimesest. See oli teda juba kaua aega vaevanud, ja teda oli ahelatega seotud ja peetud jalgrau'us, aga ta oli rauad katki kiskunud ja kuri vaim oli teda ajanud kõrbedesse.",
        30: 'Jeesus küsis temalt: "Mis su nimi on?" Tema vastas: "Leegion!" Sest palju kurje vaime oli läinud tema sisse.',
        31: 'Ja need palusid Teda, et Ta neid ei käsiks minna ära põrguhauda.',
        32: 'Aga seal oli suur seakari mäel söömas. Ja nad palusid Teda, et Ta neid lubaks minna nende sisse. Ja Ta andis neile loa.',
        33: 'Aga kui kurjad vaimud olid inimesest väljunud, läksid nad sigade sisse, ja seakari kukutas enese ülepeakaela kaldalt järve ning uppus.',
        34: 'Kui karjatsejad nägid, mis sündis, põgenesid nad ja andsid seda teada linnas ja maal.',
        35: 'Siis tuldi välja vaatama, mis oli sündinud, ja mindi Jeesuse juure ja leiti inimene, kellest kurjad vaimud olid välja läinud, Jeesuse jalge ees istumas, riietatult ja selge aruga. Ja inimesed lõid kartma.',
        36: 'Siis jutustasid neile need, kes olid näinud, kuidas seestunu oli terveks saanud.',
        37: 'Ja kogu rahvahulk gerasalaste maa ümbruskonnast palus Teda, et Ta läheks ära nende juurest. Sest suur hirm oli neid vallanud. Tema aga astus paati ja pöördus tagasi.',
        38: 'Aga mees, kellest kurjad vaimud olid välja läinud, palus Teda, et ta võiks jääda Tema juure. Kuid Jeesus laskis ta minema, üteldes:',
        39: '"Mine tagasi koju ja jutusta, mis suuri asju Jumal sulle on teinud!" Ja ta läks ära ja kuulutas mööda kogu linna, kui suuri asju Jeesus temale oli teinud.',
        40: 'Aga kui Jeesus tagasi tuli, võttis rahvas Teda vastu, sest nemad kõik olid Teda ootamas.',
        41: 'Ja vaata, siis tuli mees, Jairus nimi, ja see oli kogudusekoja ülem; ja ta heitis Jeesuse jalge ette ning palus Teda tulla enese kotta.',
        42: 'Sest tal oli ainus tütar, kaksteistkümmend aastat vana, ja see oli suremas. Aga Tema sinna minnes tungis rahvas Temale peale.',
        43: 'Ja keegi naine, kes oli kaksteistkümmend aastat põdenud verejooksu ega olnud võinud ühegi käest saada tervist,',
        44: 'tuli Tema selja taha ja puudutas Ta kuue palistust, ja sedamaid lakkas ta verejooks.',
        45: 'Ja Jeesus ütles: "Kes puudutas Mind?" Aga kui kõik salgasid, ütles Peetrus: "Õpetaja, rahvahulgad tungivad Sulle peale ja rõhuvad Sind!"',
        46: 'Kuid Jeesus ütles: "Keegi puudutas Mind, sest Ma tundsin väe Enesest välja minevat!"',
        47: 'Kui nüüd naine nägi, et ta ei olnud varjule jäänud, tuli ta värisedes ja heitis Tema ette maha ja teatas Temale kõige rahva kuuldes, mis asja pärast ta oli Teda puudutanud ja kuidas ta kohe oli terveks saanud.',
        48: 'Siis Ta ütles naisele: "Tütar, sinu usk on sind aidanud, mine rahuga!"',
        49: 'Kui Tema alles rääkis, tuli kogudusekoja ülema perest keegi ning ütles: "Su tütar on surnud, ära tülita enam Õpetajat!"',
        50: 'Aga seda kuuldes vastas Jeesus temale: "Ara karda, usu vaid, siis ta saab abi!"',
        51: 'Kui Ta siis jõudis majasse, ei lasknud Ta Enesega sisse tulla kedagi teist kui ainult Peetruse ja Johannese ja Jakoobuse ning lapse isa ja ema.',
        52: 'Ja kõik nutsid ja leinasid tütarlast. Aga Tema ütles: "Ärge nutke, ta ei ole surnud, vaid ta magab!"',
        53: 'Ja nad naersid Teda, teades, et lapsuke on surnud.',
        54: 'Ent Tema haaras lapse käest kinni ja ütles hüüdes: "Tütarlaps, tõuse üles!"',
        55: 'Ja tema vaim tuli tagasi, ja ta tõusis kohe üles. Ja Ta käskis talle süüa anda.',
        56: 'Ja tütarlapse vanemad kohkusid; aga Tema keelas neid ühelegi rääkimast seda, mis oli sündinud.',
    },
    9: {
        1: 'Aga Ta kutsus kokku need kaksteistkümmend ja andis neile väe ja meelevalla kõigi kurjade vaimude üle ja tõbesid parandada,',
        2: 'ja läkitas nad välja kuulutama Jumala Riiki ja tegema haigeid terveks,',
        3: 'ja ütles neile: "Ärge võtke midagi teele kaasa, ei keppi ega pauna, ei leiba ega raha; ärgu olgu ka kellelgi kaht kuube.',
        4: 'Ja kuhu majasse te iganes sisse lähete, sinna jääge ja sealt minge teele.',
        5: 'Ja kes iganes teid vastu ei võta, sellest linnast minge välja ja puistake toim oma jalgadelt tunnistuseks nende vastu!"',
        6: 'Nii nad läksid teele ja käisid mööda külasid, kuulutades Evangeeliumi ja tehes haigeid terveks igal pool.',
        7: 'Aga nelivürst Heroodes sai kuulda kõik, mis sündis, ja oli kahevahel, sest mõned ütlesid: "Johannes on surnuist üles tõusnud!"',
        8: 'aga teised: "Eelija on ilmunud!" aga mõned jälle: "Keegi vanust prohveteist on üles tõusnud!"',
        9: 'Ent Heroodes ütles: "Johannese pea ma lasksin maha raiuda; kes on siis See, Kellest ma kuulen niisuguseid asju?" Ja ta püüdis Teda näha saada.',
        10: 'Ja kui Apostlid tagasi tulid, jutustasid nad Temale, mis nad olid teinud. Ja Ta võttis nad Enese juure ja läks ära üksindusse, linna poole, mida hüütakse Betsaidaks.',
        11: 'Aga kui rahvahulgad seda teada said, läksid nad Temale järele. Ja Ta võttis nad vastu ja rääkis neile Jumala Riigist; ja kelledele oli vaja ravitsemist, need Ta tegi terveks.',
        12: 'Siis päev hakkas veerema. Ja need kaksteistkümmend tulid Ta juure ja ütlesid Talle: "Lase rahvas minema, et nad läheksid ümberkaudseisse küladesse ja asulaisse puhkama ja otsima rooga; sest me oleme siin tühjas paigas!"',
        13: 'Aga Ta ütles neile: "Andke teie neile süüa!" Nemad vastasid: "Meil pole rohkem kui viis leiba ja kaks kala, või me peaksime minema ja ostma toidust kogu sellele rahvale!"',
        14: 'Ent neid oli ligi viis tuhat meest. Siis Ta ütles Oma jüngritele: "Seadke nad maha istuma salkadesse viiekümne kaupa!"',
        15: 'Ja nad tegid nõnda ja seadsid kõik maha istuma einele.',
        16: 'Ent Ta võttis need viis leiba ja kaks kala, vaatas üles taeva poole, õnnistas neid ning murdis nad ja andis Oma jüngritele ettepanemiseks rahvale.',
        17: 'Ja kõlk sõid ja kõikide kõhud said täis; ja neist ülejäänud palukesi korjati kokku kaksteistkümmend korvitäit.',
        18: 'Ja sündis, kui Ta üksipäini oli palvetamas, et Ta jüngrid olid ühes Temaga. Ja Ta küsis neilt: "Keda rahvas ütleb Mind olevat?"',
        19: 'Aga nemad vastasid ning ütlesid: "Ristija Johannese, aga mõned Eelija, aga teised, et keegi vanust prohveteist on üles tõusnud!"',
        20: 'Siis Ta ütles neile: "Ent teie, keda teie ütlete Mind olevat?" Peetrus vastas ning ütles: "Jumala Kristuse!"',
        21: 'Ja Ta ähvardas neid kangesti ning keelas neid sellest ühelegi rääkimast,',
        22: 'üteldes: "Inimese Poeg peab palju kannatama ja kõlbmatuna hüljatama vanemate ja ülempreestrite ja kirjatundjate poolt ja tapetama ja kolmandal päeval jälle üles äratatama!"',
        23: 'Aga Ta ütles kõikidele: "Kui keegi tahab Minu järele tulla, see salaku end ja võtku oma rist iga päev enese peale ja järgigu Mind.',
        24: 'Sest kes iganes oma hinge tahab päästa, see kaotab selle, aga kes iganes oma hinge kaotab Minu pärast, see päästab selle!',
        25: 'Sest mis kasu on inimesel sellest, kui ta kogu maailma kasuks saaks, aga kaotaks iseenese või läheks hukka?',
        26: 'Sest kes Minu ja Mu sõnade pärast häbeneb, selle pärast häbeneb Inimese Poeg, kui Ta tuleb Omas ja Isa ja pühade Inglite auhiilguses.',
        27: 'Aga Ma ütlen teile tõesti: On mõningad siin seisjaist, kes ei maitse surma, kuni nad näevad Jumala Riiki!"',
        28: 'Ent arvata kaheksa päeva pärast neid kõnesid sündis, et Ta võttis Enesega Peetruse ja Johannese ja Jakoobuse ja läks mäele palvetama.',
        29: 'Ja kui Ta palvetas, muutus Tema näoilme teissuguseks ja Tema riietus läks valgeks ja hiilgavaks.',
        30: 'Ja vaata, kaks meest kõnelesid Temaga; need olid Mooses ja Eelija.',
        31: 'Nemad olid ilmunud auhiilguses ja kõnelesid Tema eluotsast, mis tal Jeruusalemas tuli täide saata.',
        32: 'Aga Peetrus ja ta kaaslased olid suikunud raskesse unne; ent üles ärgates nad nägid Tema auhiilgust ja neid kaht meest seisvat Tema juures.',
        33: 'Kui siis need Temast olid lahkumas, ütles Peetrus Jeesusele: "Õpetaja, siin on meil hea olla! Teeme kolm telki, ühe Sinule ja ühe Moosesele ja ühe Eelijale!" Kuid ta ei teadnud, mida ta rääkis.',
        34: 'Aga kui ta seda rääkis, tekkis pilv ja varjas nad; ja nemad kartsid pilve sisse jõudes.',
        35: 'Ja hääl kostis pilvest ning ütles: "See on Minu Äravalitud Poeg, Teda kuulake!"',
        36: 'Ja kui see hääl oli kostnud, leiti Jeesus üksi olevat. Ja nad olid vait ega kuulutanud neil päevil kellelegi midagi sellest, mida nad olid näinud.',
        37: 'Järgmisel päeval, kui nad mäelt alla läksid, tuli palju rahvast Temale vastu.',
        38: 'Ja vaata, üks mees rahvahulga seast kisendas ning ütles: "Õpetaja, ma palun Sind vaadata mu poega, sest ta on mu ainuke!',
        39: 'Ja vaata, vaim haarab teda, ja ta karjatab äkki, ja vaim raputab teda, nõnda et ta ajab suust vahtu; ja see lahkub vaevalt teda piinamast.',
        40: 'Ja mina palusin Sinu jüngreid, et nad ajaksid ta välja, ja nad ei suutnud!"',
        41: 'Aga Jeesus vastas ning ütles: "Oh sa uskmatu ja pöörane tõug! Kui kaua Ma pean olema teie juures ja kannatama teiega? Too siia oma poeg!"',
        42: 'Kui ta alles oli tulemas, kiskus teda kuri vaim ja raputas teda. Aga Jeesus sõitles rüvedat vaimu ja tegi poisi terveks ning andis ta tagasi tema isale.',
        43: 'Ent kõik hämmastusid Jumala suurest väest. Aga kui kõik panid imeks seda, mida Ta tegi, ütles Ta Oma jüngritele:',
        44: '"Pange teie oma kõrvu need sõnad. Sest Inimese Poeg antakse inimeste kätte!"',
        45: 'Ent nemad ei mõistnud seda sõna, ja see oli pandud varjule nende eest, et nad sellest aru ei saaks. Ja nad kartsid küsida temalt selle sõna kohta.',
        46: 'Aga nende seas tõusis vaidlus, kes küll nende seast peaks olema suurem.',
        47: 'Jeesus, teades nende südame mõtlemisi, võttis lapsukese ja seadis selle enese kõrvale',
        48: 'ning ütles neile: "Kes iganes selle lapsukese võtab vastu Minu nimel, võtab Mind vastu; ja kes iganes võtab vastu Mind, võtab vastu Selle, Kes Mind on läkitanud. Sest kes teist kõigist on vähem, see on suur!"',
        49: 'Siis Johannes hakkas rääkima ning ütles: "Õpetaja, me nägime üht meest Sinu nimel kurje vaime välja ajavat; ja me keelasime teda, sellepärast et ta ühes meiega Sind ei järgi!"',
        50: 'Jeesus ütles talle: "Ärge keelake, sest kes ei ole meie vastu, see on meie poolt!"',
        51: 'Aga sündis, kui Tema ülesvõtmisepäevad olid täis saamas, et ta suundus kindlasti minema Jeruusalema poole,',
        52: 'ja Ta läkitas käskjalad Enese eele. Ja need läksid ja tulid ühte samaarlaste külla, valmistama Temale öömaja.',
        53: 'Ent need ei võtnud Teda vastu, sest Ta oli minemas Jeruusalema poole.',
        54: 'Kui Ta jüngrid Jakoobus ja Johannes seda nägid, ütlesid nad: "Issand, kas tahad, et me käsime tulla tule taevast maha ja nad hävitada?"',
        55: 'Aga ta pöördus ümber ja sõitles neid.',
        56: 'Ja nad läksid teise alevisse.',
        57: 'Ja kui nad olid sinna minemas, ütles teel keegi Temale: "Issand, ma tahan Sind järgida, kuhu Sa iganes lähed!"',
        58: 'Jeesus ütles talle: "Rebastel on augud ja taeva lindudel on pesad, aga Inimese Pojal ei ole aset, kuhu Ta Oma pea paneks!"',
        59: 'Kellelegi teisele Ta ütles: "Järgi mind!" Ent see ütles: "Issand, luba mind enne minna ja oma isa maha matta!"',
        60: 'Aga Ta ütles temale: "Lase surnuid oma surnud matta, sina aga mine ja kuuluta Jumala Riiki!"',
        61: 'Ja veel üks teine ütles: "Issand, ma tahan Sind järgida! Aga luba mind enne jätta jumalaga oma kodakondsed!"',
        62: 'Aga Jeesus ütles temale: "Ükski, kes paneb oma käe adra külge ja vaatab tagasi, ei kõlba Jumala Riigile!"',
    },
    10: {
        1: 'Pärast seda määras Issand teised seitsekümmend ja läkitas nad kahekaupa enese eele igasse linna ja paika, kuhu Ta ise mõtles minna.',
        2: 'Ja Ta ütles neile: "Lõikust on palju, aga töötegijaid vähe; seepärast paluge lõikuse Issandat, et ta läkitaks välja töötegijaid Oma lõikusele!',
        3: 'Minge! Vaata, ma läkitan teid kui tallesid huntide keskele!',
        4: 'Ärge kandke kukrut ega pauna ega jalatseid ja teel ärge kedagi teretage.',
        5: 'Kuhu majasse te aga iganes sisse lähete, seal ütelge esiti: "Rahu olgu sellele kojale!"',
        6: 'Ja kui iganes seal on rahulaps, siis hingab teie rahu tema peal; aga kui mitte, siis tuleb rahu tagasi teie peale.',
        7: 'Aga sinna majasse jääge, sööge ja jooge, mis neil on, sest töötegija on oma palga väärt; ärge käige ühest majast teise.',
        8: 'Ja kuhu linna te iganes lähete ja kus teid vastu võetakse, seal sööge, mida teile ette pannakse;',
        9: 'ja tehke selle paiga haiged terveks ja ütlege neile: Jumala Riik on teie lähedal!',
        10: 'Aga kuhu linna te iganes lähete ja kus teid vastu ei võeta, seal minge välja ta uulitsaile ning ütelge:',
        11: 'Tolmugi, mis teie linnast on hakanud meie jalgade kulge, me pühime ära teile; ometi teadke, et Jumala Riik on lähedal!',
        12: 'Ma ütlen teile, et Soodomal on sel päeval Hõlpsam põli kui tol linnal!',
        13: 'Häda sulle, Korasin, häda sulle, Betsaida! Sest kui Tüüroses ja Siidonis oleksid sündinud need vägevad teod, mis teie juures on sündinud, küll nad oleksid ammu kotiriides ja tuhas istudes parandanud meelt!',
        14: 'Ometi peab Tüürosel ja Siidonil olema kohtus hõlpsam põli kui teil!',
        15: 'Ja sina, Kapernaum, eks sa olnud ülendatud taevani? Sind tõugatakse põrguni alla!',
        16: 'Kes teid kuuleb, see kuuleb Mind, ja kes teid hülgab, see hülgab Mind; aga kes hülgab Mind, see hülgab Selle, Kes Mind on läkitanud!"',
        17: 'Siis need seitsekümmend tulid tagasi rõõmuga ja ütlesid: "Issand, ka kurjad vaimud alistuvad meile Sinu nime tõttu!"',
        18: 'Aga Ta ütles neile: "Ma nägin saatana nagu välgu taevast maha langevat!',
        19: 'Vaata, Ma olen annud teile meelevalla astuda madude ja skorpionide peale ja vaenlase kõige väe peale; ja miski ei tee teile kahju.',
        20: 'Ometi ärge rõõmutsege, et vaimud teile alistuvad, vaid rõõmutsege palju enam sellest, et teie nimed on taevasse kirja pandud!"',
        21: 'Selsamal tunnil Ta rõõmustus Pühas Vaimus ja ütles: "Mina tänan Sind, Isa, taeva ja maa Issand, et Sa oled tarkade ja mõistlike eest selle pannud varjule ja oled selle ilmutanud väetimaile! Jah, Isa, see on nõnda olnud Sulle meelepärast!',
        22: 'Kõik on Mu Isa Mulle annud! Ja ükski ei tunne, kes on Poeg, kui vaid Isa, ja kes on Isa, kui vaid Poeg ja kellele iganes Poeg tahab ilmutada!"',
        23: 'Ja Ta pöördus jüngrite poole eriti ning ütles: "Õndsad on silmad, kes näevad, mida teie näete!',
        24: 'Sest Ma ütlen teile, et palju prohveteid ja kuningaid on tahtnud näha, mida teie näete, ja ei ole näinud, ja kuulda, mida teie kuulete, ja ei ole kuulnud!"',
        25: 'Ja vaata, keegi käsutundja astus esile, kiusas Teda ja ütles: "Õpetaja, mis ma pean tegema, et ma päriksin igavese elu?"',
        26: 'Aga Tema ütles talle: "Mis on käsuõpetuses kirjutatud? Kuidas sa loed?"',
        27: 'Tema vastas ning ütles: "Armasta Issandat, oma Jumalat, kõigest oma südamest ja kõigest oma hingest ja kõigest oma jõust ja kõigest oma meelest, ja oma ligimest nagu iseennast."',
        28: 'Aga Ta ütles temale: "Sa oled õieti vastanud; tee seda, ja sa pead elama!"',
        29: 'Tema aga tahtis iseennast õigeks teha ja ütles Jeesusele: "Kes siis on mu ligimene?"',
        30: 'Aga vastates Jeesus ütles: "Üks inimene läks Jeruusalemast alla Jeerikosse ja sattus röövlite kätte. Kui need ta riided olid riisunud ja temale hoope annud, läksid nad ära, jättes ta poolsurnuna maha.',
        31: 'Juhtumisi tuli keegi preester sedasama teed mööda alla ja nägi teda ning läks mööda.',
        32: 'Nõndasamuti ka leviit. Kui ta tuli sinna paika ja nägi teda, läks ta mööda.',
        33: 'Aga üks samaarlane käis seda teed ja tuli tema juure; ja kui ta teda nägi, läks ta meel haledaks.',
        34: 'Ja ta astus ligi, sidus ta haavad ning valas peale õli ja viina, tõstis ta oma looma selga ning viis ta öömajale ja kandis hoolt tema eest.',
        35: 'Ja teisel hommikul ära minnes võttis ta välja kaks teenarit, andis need peremehele ja ütles: Kanna hoolt tema eest, ja mida sa veel peaksid kulutama, seda ma maksan sulle tagasi tulles.',
        36: 'Kes neist kolmest oli sinu arvates ligimene sellele, kes oli sattunud röövlite kätte?"',
        37: 'Aga tema ütles: "See, kes tema peale halastas!" Siis ütles Jeesus temale: "Mine ja tee sina nõndasamuti!"',
        38: 'Aga kui nad rändasid, läks Ta ühte alevisse. Ent üks naine, Marta nimi, võttis Tema vastu oma majasse.',
        39: 'Ja temal oli õde, keda hüüti Maarjaks; seegi istus Issanda jalge ees ja kuulas Tema kõnet.',
        40: 'Marta aga tegi tegemist mitmesuguse talitusega. Ta tuli sinna ja ütles: "Issand, kas Sa ei hooli sellest, et mu õde laseb mind üksi talitada? Ütle ometi temale, et ta mind aitaks!"',
        41: 'Aga Issand vastas ning ütles talle: "Marta, Marta, sa muretsed ja teed enesele tüli paljude asjadega;',
        42: 'kuid tarvis on vähe, õigupoolest üht! Maarja on selle hea osa valinud ja seda ei võeta temalt ära!"',
    },
    11: {
        1: 'Ja kui Ta ühes paigas oli palvetamas ja oli lõpetanud, ütles üks Ta jüngreist Temale: "Issand, õpeta meid palvetama nõnda nagu Johannes õpetas oma jüngreid!"',
        2: 'Aga Ta ütles neile: "Kui te palvetate, siis ütelge: Isa! Pühitsetud olgu Sinu nimi; Sinu riik tulgu;',
        3: 'meie igapäevane leib anna meile iga päev;',
        4: 'ja anna meile andeks meie patud, sest meiegi anname andeks igaühele, kellel on meiega võlgu; ja ära saada meid kiusatusse!"',
        5: 'Ja Ta ütles neile: "Kellel teie seast on sõber ja ta läheks südaöösel ta juure ja ütleks temale: Sõber, laena mulle kolm leiba,',
        6: 'sest mu sõber on teelt tulnud mu juure ja mul ei ole, mida talle ette paneksin!',
        7: 'Kas tema peaks toast vastama ning ütlema: Ära tee mulle tüli, uks on juba lukus ja mu lapsukesed on minuga voodis; ma ei või üles tõusta sulle andma!?',
        8: 'Ma ütlen teile, kui ta üles ei tõuseks ja talle ei annaks, sellepärast et ta on tema sõber, siis tõuseks ta ometi üles tema pealekäimise pärast ning annaks talle, niipalju kui talle vaja.',
        9: 'Ka Mina ütlen teile: Paluge, siis antakse teile; otsige, siis te leiate; koputage, siis avatakse teile.',
        10: 'Sest igaüks, kes palub, see saab, ja kes otsib, see leiab, ja kes koputab, sellele avatakse.',
        11: 'Ent missugune isa on teie seas, kellelt poeg palub kala, et ta annaks sellele kala asemel mao?',
        12: 'Või kui ta palub muna, ta annaks talle skorpioni?',
        13: 'Kui nüüd teie, kes olete kurjad, märkate anda häid ande oma lastele, kui palju enam Isa taevast annab Püha Vaimu neile, kes Teda paluvad."',
        14: 'Ja kord Ta ajas kurja vaimu välja; ja see oli keeletu. Aga kui kuri vaim oli väljunud, hakkas keeletu rääkima ja rahvahulgad panid seda imeks.',
        15: 'Aga mõningad nende seast ütlesid: "Ta ajab kurje vaime välja Peeltsebuli, kurjade vaimude ülema abil!"',
        16: 'Aga teised kiusasid Teda ning nõudsid Temalt tunnustähte taevast.',
        17: 'Ent Tema mõistis ära nende mõtted ja ütles neile: "Iga kuningriik, mis on isekeskis riius, hävib ja koda langeb koja peale.',
        18: 'Kui saatangi on riius isekeskis, kuidas võib tema kuningriik püsida? Te ju ütlete, et Mina ajavat kurje vaime välja Peeltsebuli abil!',
        19: 'Aga kui Mina kurje vaime välja ajan Peeltsebuli abil, kelle abil ajavad teie pojad neid välja? Sellepärast saavad nemad teie kohtumõistjaiks.',
        20: 'Ent kui Mina kurje vaime välja ajan Jumala sõrmega, siis on Jumala Riik jõudnud teie juure.',
        21: 'Kui vägev relvastatud mees valvab oma elamut, siis on ta vara rahus.',
        22: 'Aga kui temast vägevam peale tuleb ja võidab tema, siis ta võtab ära kõlk ta relvad, millede peale ta lootis, ja jagab temalt saadud saagi välja.',
        23: 'Kes Minu poolt ei ole, on Minu vastu; ja kes Minuga ei kogu, see hajutab.',
        24: 'Kui rüve vaim on inimesest välja läinud, käib ta mööda põudseid paiku ja otsib hingamist. Ja kui ta ei leia, ütleb ta: Ma pöördun tagasi oma kotta, kust ma väljusin!',
        25: 'Ja kui ta tuleb, leiab ta selle pühitud ning ehitud olevat.',
        26: 'Siis ta läheb ja võtab kaasa teist seitse vaimu, kes on kurjemad temast, ja nad tulevad sisse ning elavad seal. Ja selle inimese viimne lugu läheb pahemaks kui eelmine!"',
        27: 'Kui Ta seda rääkis, sündis, et üks naine rahva seast tõstis oma häält ning ütles Temale: "Õnnis on ihu, mis Sind on kannud, ja rinnad, mida Sina oled imenud!"',
        28: 'Aga Tema ütles: "Jah, õndsad on need, kes Jumala sõna kuulevad ja seda tallele panevad!"',
        29: 'Kui rahvahulki murdu kokku tuli, hakkas Ta kõnelema: "See sugu on paha sugu; ta otsib tunnustähte, ja talle ei anta muud tähte kui vaid prohvet Joona täht.',
        30: 'Sest nõnda nagu Joona sai täheks Niinive elanikele, nõnda peab ka Inimese Poeg olema sellele soole.',
        31: 'Lõunamaa kuninganna tõuseb üles kohtupäeval selle soo meeste kõrval ja mõistab nad hukka; sest ta tuli ilmamaa otsast kuulama Saalomoni tarkust. Ja vaata, siin on rohkem kui Saalomon!',
        32: 'Niinive mehed tõusevad üles kohtupäeval selle soo kõrval ja mõistavad selle hukka; sest nad parandasid meelt Joona jutluse tõttu. Ja vaata, siin on rohkem kui Joona!',
        33: 'Ükski ei süüta küünalt ega pane seda varjule ega vaka alla, vaid küünlajalale, et sissetulijad valgust näeksid.',
        34: 'Ihu küünal on su silm. Kui su silm on korras, siis on ka kõik su ihu valguses; aga kui ta on rikkis, siis on ka su ihu pime.',
        35: 'Katsu siis, et valgus, mis on sinu sees, ei oleks pimedus!',
        36: 'Kui nüüd kogu su ihu on valguses, nõnda et tal sugugi ei ole pimedust, siis on ta täiesti valgustatud, nõnda nagu küünal valgustaks sind oma välkuva leegiga!"',
        37: 'Kui Tema alles nõnda rääkis, palus Teda keegi variser enese juure lõunat sööma. Ja Ta läks sisse ja istus lauda.',
        38: 'Aga variser pani imeks, kui ta nägi, et Ta enne söömist ennast ei pesnud.',
        39: 'Siis Issand ütles temale: "Teie, variserid, teete küll väljastpoolt puhtaks karika ja vaagna, aga seestpoolt te olete täis rüüstet ja kurjust!',
        40: 'Te mõistmatumad! Eks see, kes tegi välispidise, ole teinud ka seespidise?',
        41: 'Ent andke armuanniks, mis teie sees on, ja vaata, siis on teile kõik puhas!',
        42: 'Aga häda teile, variseridele, et te maksate kümnist mündist ja ruudist ja kõigest aiarohust ja lähete mööda õiglusest ja Jumala armastusest! Seda peab tegema ja teist ei tohi tegemata jätta!',
        43: 'Häda teile variseridele, et te armastate esimest istet kogudusekodades ja teretusi turgudel!',
        44: 'Häda teile, et te olete nagu äravajunud hauad, ja inimesed käivad nende peal, ilma et nad teaksid!"',
        45: 'Aga üks käsutundjaist kostis ja ütles Temale: "Õpetaja, seda üteldes sa teotad ka meid!"',
        46: 'Ent Tema ütles: "Häda ka teile käsutundjaile, sest te panete inimestele peale rängad koormad ja ise ei puutu ühe oma sõrmegagi neisse koormaisse!',
        47: 'Häda teile, et te ehitate prohvetitele hauamärke, aga teie isad on nad tapnud!',
        48: 'Nii te olete ise tunnistajad, et teil on hea meel oma isade tegudest; sest nemad tapsid nad, aga teie ehitate nende hauamärke!',
        49: 'Sellepärast ütleb ka Jumala tarkus: Ma läkitan nende juure prohveteid ja apostleid, ja nad tapavad mõned neist ja kiusavad neid taga,',
        50: 'et sellelt sugupõlvelt nõutaks kõigi prohvetite verd, mis on ära valatud alates maailma asutamisest,',
        51: 'Aabeli verest Sakarja verest saadik, kes sai hukka altari ja Jumala koja vahel. Tõesti, Ma ütlen teile, seda nõutakse sellelt sugupõlvelt!',
        52: 'Häda teile käsutundjaile, et te olete ära võtnud tunnetuse võtme! Ise te ei ole sisse läinud ja olete keelanud neid, kes sisse läheksid!"',
        53: 'Ja kui Ta sealt väljus, hakkasid kirjatundjad ja variserid Teda kangesti kimbutama ja usutlema mitmeis asjus,',
        54: 'et kavaldamisega midagi Tema suust kätte saada.',
    },
    12: {
        1: 'Kui sel ajal rahvast oli tuhandeti kokku tulnud, nõnda et nad üksteist tallasid, hakkas Ta kõigepealt kõnelema Oma jüngritele: "Hoiduge variseride haputaigna, see on silmakirjalikkuse eest!',
        2: 'Ei ole midagi varjatud, mis ei tuleks ilmsiks, ega ole midagi salajas, mida ei saadaks teada.',
        3: 'Sellepärast peab kõike, mida te ütlete pimedas, kuuldama valges; ja mida te üksteise kõrva räägite kambrites, seda peab kuulutatama katustelt!',
        4: 'Aga Ma ütlen teile, Oma sõpradele: Ärge kartke neid, kes tapavad ihu ja pärast ei saa rohkem midagi teha.',
        5: 'Ent Ma näitan teile, keda teil tuleb karta: kartke teda, kellel on meelevald pärast tapmist heita põrgusse. Tõesti, Ma ütlen teile, teda kartke!',
        6: 'Eks viis varblast müüda kahe veeringu eest? Ja ükski neist ei ole unustatud Jumala ees!',
        7: 'Aga teie juuksekarvadki on kõik ära loetud! Ärge kartke, teie olete hinnalisemad kui palju varblasi!',
        8: 'Ent Ma ütlen teile: Kes iganes Mind tunnistab inimeste ees, seda tunnistab ka Inimese Poeg Jumala Inglite ees!',
        9: 'Aga kes Mind salgab inimeste ees, see salatakse Jumala Inglite ees!',
        10: 'Ja igaüks, kes Inimese Poja vastu räägib sõna, sellele antakse andeks; aga sellele, kes pilkab Püha Vaimu, ei anta mitte andeks!',
        11: 'Aga kui teid viiakse kogudusekodadesse ja ülemate ja valitsejate ette, ärge olge mures, kuidas või mida te enese eest kostate või mida ütlete;',
        12: 'sest Püha Vaim õpetab teile selsamal tunnil, mida tuleb ütelda!"',
        13: 'Siis keegi rahva seast ütles Talle: "Õpetaja ütle mu vennale, et ta minuga jagaks pärandi!"',
        14: 'Aga Tema ütles talle: "Inimene, kes on Mind seadnud teile kohtumõistjaks või jagajaks?"',
        15: 'Ja Ta ütles neile: "Vaadake ette ja hoiduge ahnuse eest; sest külluseski ei olene kellegi elu sellest, mis tal on!"',
        16: 'Ja Ta rääkis neile ka tähendamissõna, üteldes: "Ühe rikka mehe põllumaa oli hästi vilja kannud.',
        17: 'Ja ta mõtles iseeneses nõnda: Mis ma teen? Sest mul ei ole, kuhu ma koguksin oma vilja.',
        18: 'Ja ta ütles: Seda ma teen: ma kisun maha oma aidad ja ehitan suuremad, ja sinna ma kogun kõik oma vilja ja oma vara,',
        19: 'ja ütlen oma hingele: Hing, sul on palju hüüt tagavaraks mitmeks aastaks; ole nüüd rahul, söö, joo ja ole rõõmus!',
        20: 'Aga Jumal ütles temale: Sina meeletu! Selsamal ööl nõutakse sult sinu hing; kellele saab siis, mis sa oled soetanud?',
        21: 'Nõnda on selle lugu, kes enesele kogub tagavara ja ei ole rikas Jumalas!"',
        22: 'Siis Ta ütles oma jüngritele: "Seepärast ma ütlen teile: Ärge olge mures oma hinge pärast, mida süüa, ega oma ihu pärast, millega riietuda!',
        23: 'Sest hing on enam kui toidus ja ihu enam kui riided!',
        24: 'Pange tähele kaarnaid! Nad ei külva ega lõika; neil ei ole varakambrit ega aita, ja Jumal toidab neid. Kui palju hinnalisemad olete teie kui on linnud!',
        25: 'Aga kes teie seast võib muretsemisega oma pikkusele ühegi küünra jätkata?',
        26: 'Kui te nüüd kõige vähematki ei suuda, miks te siis olete mures muu pärast?',
        27: 'Pange tähele lilli, kuidas nad ei ketra ega koo; aga ma ütlen teile: Saalomongi kõiges oma hiilguses pole olnud nõnda ehitud kui üks nendest!',
        28: 'Kui nüüd Jumal rohtu, mis täna kasvab ja homme visatakse ahju, nõnda ehib, kui palju enam teid, te nõdrausulised!',
        29: 'Ka teie ärge küsige, mida süüa või mida juua, ja ärge olge kärsitumad!',
        30: 'Sest kõike seda nõuavad taga maailma rahvad; teie Isa teab ju, et te seda vajate.',
        31: 'Otsige vaid Tema Riiki, ja see kõlk antakse teile pealegi!',
        32: 'Ära karda, sa pisuke karjuke, sest teie Isa on heaks arvanud anda teile Kuningriigi!',
        33: 'Müüge ära, mis teil on, ja andke armuande! Valmistage enestele kukrud, mis ei vanane, ja varandus taevas, mis ei vähene, kuhu varas ligi ei pääse ja mida koi ei riku!',
        34: 'Sest kus teie varandus on, seal on ka teie süda!',
        35: 'Teie niuded olgu vöötatud ja küünlad põlegu!',
        36: 'Ja teie olge inimeste sarnased, kes ootavad oma isandat, millal ta lahkub pulmast, et kui ta tuleb ja koputab, nad kohe temale avaksid.',
        37: 'Õndsad on need sulased, keda isand tulles leiab valvamast! Tõesti, Ma ütlen teile, tema vöötab enese ja paneb nad lauda istuma ja tuleb ja teenib neid!',
        38: 'Ja tulgu ta teisel või kolmandal öövahikorral, kui ta nad leiab nõnda - õndsad on need sulased!',
        39: 'Aga seda teadke: Kui peremees teaks, mil tunnil varas tuleb, ta ei laseks oma kotta sisse murda!',
        40: 'Olge siis ka teie valmis, sest Inimese Poeg tuleb tunnil, mil te ei arvagi!"',
        41: 'Aga Peetrus küsis: "Issand, kas ütled selle tähendamissõna meile või kõikidele?"',
        42: 'Ja Issand ütles: "Kes on siis ustav ja mõistlik majapidaja, keda isand seab oma pere üle neile õigel ajal andma määratud moona?',
        43: 'Õnnis see sulane, keda isand tulles leiab nõnda tegemast!',
        44: 'Tõesti, Ma ütlen teile, ta paneb tema üle kõige oma vara!',
        45: 'Aga kui see sulane ütleb oma südames: Mu isand viibib tulles! ja ta hakkab peksma poisse ja tüdrukuid, ja sööma ja jooma ja purjutama,',
        46: 'siis selle sulase isand tuleb päeval, mil ta ei oota teda, ja tunnil, mida ta ei tea, ja raiub ta pooleks ja annab temale osa ühes uskmatutega.',
        47: 'Aga sulane, kes teadis oma isanda tahtmist, aga ei valmistanud ega teinud tema tahtmise järele, saab palju hoope.',
        48: 'Aga kes ei teadnud, kuid tegi, mis on hoopide väärt, saab pisut hoope. Sest kellele on palju antud, sellelt nõutakse palju; ja kelle hoole on palju jäetud, sellelt päritakse veel rohkem!',
        49: 'Tuld Ma tulin viskama maa peale; ja mis Ma muud tahaksin, kui et see juba oleks süüdatud!',
        50: 'Aga Mind peab ristitama ristimisega, ja kuidas on mul kitsas käes, kuni see on lõpetatud!',
        51: 'Kas mõtlete, et Ma olen tulnud andma rahu maa peale? Mitte sugugi, ütlen Ma teile, vaid lahkmeelt!',
        52: 'Sest nüüdsest alates peavad viis ühes majas olema lahkmeeles, kolm kahe vastu ja kaks kolme vastu,',
        53: 'isa poja vastu ja poeg isa vastu, ema tütre vastu ja tütar ema vastu, ämm oma minia vastu ja minia ämma vastu!"',
        54: 'Aga Ta ütles ka rahvale: "Kui te näete pilve tõusvat lääne poolt, siis te kohe ütlete: Raske sadu tuleb! Ja see sünnib nõnda.',
        55: 'Ja kui näete lõunatuult puhuvat, siis te ütlete: Kuum tuleb! Ja see sünnib nõnda.',
        56: 'Te silmakirjatsejad! Maa ja taeva nägu te oskate mõista, aga kuidas te ei mõista sedasinast aega?',
        57: 'Ja miks te ka iseenestest ei otsusta, mis on õige?',
        58: 'Sellepärast kui sa oma vastasega lähed ülema ette, siis püüa temaga asi lahendada teel, et ta sind ei veaks kohtuniku ette ja kohtunik sind ei annaks kohtusulase kätte ja kohtusulane sind ei heidaks vanglasse.',
        59: 'Ma ütlen sulle, et sa ei pääse sealt, enne kui maksad viimse leptoni!"',
    },
    13: {
        1: 'Selsamal ajal olid saabunud mõned, kes jutustasid Temale galilealastest, kellede vere Pilaatus oli seganud nende ohvritega.',
        2: 'Ja Jeesus hakkas kõnelema ning ütles neile: "Kas arvate, et need galilealased olid suuremad patused kui kõik muu Galilea rahvas, et nad seda said kannatada?',
        3: 'Ma ütlen teile, et mitte sugugi, vaid kui te ei paranda meelt, lähete kõik samuti hukka!',
        4: 'Või arvate, et need kaheksateistkümmend, kellede peale langes Siiloa torn ja tappis nad, olid suuremad süüalused kui kõik inimesed, kes elavad Jeruusalemas?',
        5: 'Ma ütlen teile, et mitte sugugi, vaid kui te ei paranda meelt, siis lähete kõik samuti hukka!"',
        6: 'Ja Ta ütles selle tähendamissõna: "Ühel inimesel oli viigipuu; see oli istutatud tema viinamäkke. Ja ta tuli ning otsis sellelt vilja, aga ei leidnud.',
        7: 'Siis ta ütles viinamäe aednikule: Vaata, kolm aastat ma käin otsimas sellelt viigipuult vilja, aga ei leia. Raiu ta maha! Miks ta maad raiskab?',
        8: 'Aga see vastas ning ütles talle: Isand, jäta ta veel sellekski aastaks, kuni ma ta ümber kaevan ja talle panen sõnnikut!',
        9: 'Ehk ta hakkab edaspidi vilja kandma; aga kui mitte, siis raiu ta maha!"',
        10: 'Ja Ta oli õpetamas ühes kogudusekojas hingamispäeval.',
        11: 'Ja vaata, seal oli naine, kellel oli olnud haiguse vaim kaheksateistkümmend aastat; naine oli küürus ega saanud ennast sugugi sirgeks ajada.',
        12: 'Teda nähes kutsus Jeesus ta enese juure ja ütles talle: "Naine, sa oled lahti oma haigusest!"',
        13: 'Ja Ta pani oma käed tema peale; ja kohe ajas naine enese sirgeks ja andis Jumalale au.',
        14: 'Aga kogudusekoja ülem, kes pahandus sellest, et Jeesus tegi terveks hingamispäeval, hakkas rääkima ning ütles rahvale: "Kuus päeva on, mil tööd tehakse; tulge ometi neil päevil ja laske endid ravida, aga mitte hingamispäeval!"',
        15: 'Aga Issand vastas temale ning ütles: "Te silmakirjatsejad! Eks igaüks teie seast päästa oma härja või eesli sõime küljest hingamispäeval ja vii teda jooma?',
        16: 'Kas siis teda, kes on Aabrahami tütar, keda saatan, vaata, kaheksateistkümmend aastat on sidunud, ei pidanud päästetama sellest köidikust hingamispäeval?"',
        17: 'Ja kui Ta seda ütles, häbenesid kõik ta vastased, ja kogu rahvas rõõmustus kõigist aulistest tegudest, mida Tema tegi.',
        18: 'Siis Ta ütles: "Mille sarnane on Jumala Riik ja millega Ma võrdlen seda?',
        19: 'See on sinepiivakese sarnane, mille inimene võttis ja külvas oma aeda; ja see kasvas ja sai puuks, ja taeva linnud tegid pesad tema okstele!"',
        20: 'Ja Ta ütles veel: "Millega Ma võrdleksin Jumala Riiki?',
        21: 'See on haputaigna sarnane, mille üks naine võttis ja segas kolme vaka jahu hulka, kuni kõik läks hapnema!"',
        22: 'Ja Ta rändas mööda linnu ja külasid õpetades ja edasi minnes teed Jeruusalemma.',
        23: 'Siis küsis keegi Temalt: "Issand, kas on pisut neid, kes saavad õndsaks?" Aga Tema ütles neile:',
        24: '"Võidelge, et te läheksite sisse kitsast uksest, sest paljud, ütlen ma teile, püüavad sisse minna, aga ei jaksa mitte!',
        25: 'Sellest ajast, kui peremees on üles tõusnud ja on pannud ukse lukku, hakkate te seisma õues ja koputama uksele, üteldes: Issand, ava meile! Ja Tema vastab teile, üteldes: Mina ei tunne teid, kust te olete!',
        26: 'Siis te hakkate ütlema: Me oleme Sinu ees Söönud ja joonud ja meie uulitsais Sa õpetasid!',
        27: 'Ja Tema ütleb teile: Ma ei tunne teid, kust te olete! Jääge Minust eemale, kõik ülekohtutegijad!',
        28: 'Seal on ulumine ja hammaste kiristamine, kui te näete Aabrahami ja Iisakit ja Jaakobit ja kõiki prohveteid Jumala Riigis, kuid endid olevat välja tõugatud.',
        29: 'Ja tuleb inimesi idast ja läänest, põhjast ja lõunast, ja nad istuvad lauas Jumala riigis.',
        30: 'Ja vaata, on viimseid, kes saavad esimesiks, ja esimesi, kes jäävad viimseiks!"',
        31: 'Samal tunnil tulid mõned variserid ja ütlesid Temale: "Välju ja mine siit ära, sest Heroodes tahab sind tappa!"',
        32: 'Tema ütles neile: "Minge ja ütelge sellele rebasele: Vaata, Ma ajan kurje vaime välja ja teen terveks täna ja homme ja kolmandal päeval ma jõuan eesmärgile!',
        33: 'Siiski Ma pean veel rändama täna ja homme ja tunahomme; sest see ei sobi, et prohvet saab hukka mujal kui Jeruusalemas!',
        34: 'Jeruusalem, Jeruusalem, kes tapad prohvetid ja viskad kividega surnuks need, kes sinu juure on läkitatud! Kui mitu korda Ma olen tahmud koguda sinu lapsi otsegu kana oma poegi tiibade alla, aga teie ei ole tahtnud!',
        35: 'Vaata, teie koda jäetakse teil maha! Ja tõesti, Ma ütlen teile, et te ei näe Mind enne, kui tuleb aeg, mil te ütlete: Õnnistatud olgu, kes tuleb Issanda nimel!"',
    },
    14: {
        1: 'Ja sündis, kui Tema hingamispäeval tuli ühe variseride ülema kotta leiba võtma, et nad varitsesid Teda.',
        2: 'Ja vaata, üks vesitõbine inimene oli Tema ees!',
        3: 'Ja Jeesus hakkas rääkima kirjatundjatele ja variseridele ning ütles: "Kas on luba hingamispäeval terveks teha?"',
        4: 'Aga nad jäid vait. Ja puudutades Ta tegi tema terveks ja laskis ta minna.',
        5: 'Siis Ta ütles neile: "Kes on teie seast, kelle poeg või härg kukub kaevu, et ta teda kohe välja ei tõmba hingamispäeval?"',
        6: 'Ja nad ei suutnud selle peale midagi vastata.',
        7: 'Aga tähele pannes, kuidas need, kes olid kutsutud, valisid ülemaid istekohti, rääkis Ta neile tähendamissõna ning ütles neile:',
        8: '"Kui sind keegi on pulma kutsunud, siis ära istu ülemasse paika, sest vahest on tema poolt kutsutud keegi sinust aulisem,',
        9: 'ja et see, kes sind ja teda kutsus, ei ütleks sulle: Anna sellele aset! ja sa peaksid siis häbiga istuma alamasse paika.',
        10: 'Aga kui sa oled kutsutud, siis mine ja istu alamasse paika, ja kui tuleb see, kes sind kutsus, ja ütleb sulle: Sõber, mine sinna ülemale! siis on sul au nende ees, kes sinuga istuvad ühes lauas.',
        11: 'Sest igaüht, kes ennast ülendab, alandatakse, ja kes ennast alandab, ülendatakse!"',
        12: 'Aga Ta ütles ka sellele, kes Teda oli kutsunud: "Kui sa teed lõuna- või õhtusöömaaja, siis ära kutsu oma sõpru ega oma vendi ega oma sugulasi ega rikkaid naabreid, et nad sind jälle ei kutsuks endi juure ja sina nõnda saaksid tasu,',
        13: 'vaid kui sa teed võõruspidu, siis kutsu vaeseid, vigaseid, jalutumaid, pimedaid;',
        14: 'siis sa oled õnnis, sest neil ei ole midagi sulle tasuda, kuna see tasutakse sulle õigete ülestõusmises!"',
        15: 'Kui üks lauas kaasistujaist seda kuulis, ütles ta Temale: "Õnnis on, kes leiba sööb Jumala Riigis!"',
        16: 'Aga Ta ütles temale: "Üks inimene tegi suure õhtusöömaaja ja kutsus paljusid.',
        17: 'Ja õhtusöömaaja tunnil ta läkitas oma sulase kutsutuile ütlema: Tulge, sest kõik on juba valmis!',
        18: 'Ja nad hakkasid endid kõik ühest suust vabandama. Esimene ütles talle: Ma olen ostnud põllu ja pean välja minema seda vaatama; ma palun sind, vabanda mind!',
        19: 'Ja teine ütles: Ma olen ostnud viis paari härgi ja lähen neid katsuma; ma palun sind, vabanda mind!',
        20: 'Ja veel teine ütles: Ma olen võtnud naise ega saa sellepärast tulla!',
        21: 'Ja sulane tuli tagasi ja teatas seda oma isandale. Siis vihastus kojaisand ja ütles oma sulasele: Mine kohe välja linna laiadele uulitsatele ja kurudesse ja too siia sisse vaesed ja vigased ja jalutumad ja pimedad!',
        22: 'Ja sulane ütles: Isand, see on tehtud, nõnda nagu sa käskisid; aga veel on ruumi!',
        23: 'Ja isand ütles sulasele: Mine välja teede peale ja aedade ääre ja sunni sisse tulema, et minu koda täis saaks!',
        24: 'Sest Ma ütlen teile, et ükski neist kutsutud meestest ei saa maitsta Mu õhtusöömaaega!"',
        25: 'Aga Temaga ühes käis palju rahvast ja Tema pöördus ning ütles neile:',
        26: '"Kui keegi tuleb Minu juure ja ei vihka oma isa ja ema ja naist ja lapsi ja vendi ja õdesid ja veel pealegi oma elu, see ei või olla Mu jünger.',
        27: 'Ja kes ei kanna oma risti ega käi Minu järel, see ei või olla Mu jünger.',
        28: 'Sest kes teie seast, kui ta tahab ehitada torni, ei istu enne maha ega arva kulu, kas temal on, mis vaja läheb teostamiseks?',
        29: 'Et kui ta aluse on rajanud ega suuda lõpetada, kõik vaatajad teda ei hakkaks naerma,',
        30: 'üteldes: See mees hakkas ehitama ega suuda lõpule viia!',
        31: 'Või missugune kuningas, minnes sõtta võitlema teise kuningaga, ei istu enne maha ega pea nõu, kas ta võib minna kümne tuhandega selle vastu, kes kahekümne tuhandega ta peale tuleb?',
        32: 'Ja kui mitte, eks ta läkita, kui teine alles on kaugel, ja palu rahu?',
        33: 'Nõnda ka igaüks teie seast, kes mitte ei loobu kõigest, mis tal on, ei või olla Mu jünger.',
        34: 'Sool on hea; aga kui sool tuimub, millega seda teha soolaseks?',
        35: 'Ei see kõlba maasse ega sõnnikusse; see visatakse välja! Kellel kõrvad on kuulda, see kuulgu!"',
    },
    15: {
        1: 'Aga kõik tölnerid ja patused lähenesid Temale, Teda kuulama.',
        2: 'Ja variserid ja kirjatundjad nurisesid ning ütlesid: "See võtab patuseid vastu ja sööb ühes nendega!"',
        3: 'Aga Ta rääkis neile selle tähendamissõna ning ütles:',
        4: '"Kes teie seast, kui tal on sada lammast ja ühe neist kaotab, ei jäta need üheksakümmend üheksa kõrbe ega lähe kadunule järele, kuni ta tema leiab?',
        5: 'Ja kui ta on leidnud, võtab ta rõõmuga tema oma õlgadele,',
        6: 'ja kui ta koju tuleb, ta kutsub kokku sõbrad ja naabrid ning ütleb neile: Rõõmutsege ühes minuga, sest ma leidsin oma lamba, kes oli kadunud!',
        7: 'Ma ütlen teile, nõnda on taevas ühest patusest, kes meelt parandab, rohkem rõõmu kui üheksakümne üheksast õigest, kes meeleparandust ei vaja!',
        8: 'Või kui ühel naisel on kümme drahmiraha ja ta kaotab ühe drahmi, eks ta süüta küünla ja pühi koda ja otsi hoolega, kuni ta selle leiab?',
        9: 'Ja kui ta selle on leidnud, siis ta kutsub kokku sõbrad ja naabrid ja ütleb: Rõõmutsege ühes minuga, sest ma olen leidnud drahmiraha, mille ma kaotasin!',
        10: 'Nõnda, ütlen Ma teile, tõuseb rõõm Jumala Inglite keskel ühest patusest, kes meelt parandab!"',
        11: 'Veel ütles ta: "Ühel inimesel oli kaks poega.',
        12: 'Ja noorem neist ütles isale: Isa, anna mulle kätte see osa vara, mis saab minule! Ja isa jagas varanduse nende vahel.',
        13: 'Ja ei möödunud palju päevi, kui noorem poeg kogus kokku kõik ja siirdus kaugele maale, ja seal ta pillas ära oma vara, elades kõlvatumat elu.',
        14: 'Aga kui ta kõik oli ära raisanud, tuli sinna maale kange nälg, ja puudus hakkas talle kätte tulema.',
        15: 'Ja ta läks ja poetas enese ühe kodaniku juure seal maal, ja see saatis ta oma väljadele sigu hoidma.',
        16: 'Ja ta püüdis oma kõhtu täita kaunadega, mida sead sõid; ja ükski ei annud temale.',
        17: 'Aga kui ta keskenes endasse, ütles ta: Kui palju palgalisi on mu isal ja neil on leiba küllalt, mina aga suren siia nälja kätte!',
        18: 'Ma asun teele ning lähen oma isa juure ja ütlen temale: Isa, ma olen pattu teinud taeva vastu ja sinu ees',
        19: 'ega ole enam väärt, et mind su pojaks hüütaks; pea mind kui üht oma palgalist!',
        20: 'Ja ta läks teele ja tuli oma isa juure. Aga kui ta alles kaugel oli, nägi teda tema isa ja tal hakkas hale meel. Ja ta jooksis ja hakkas temale ümber kaela ja andis temale suud.',
        21: 'Aga poeg ütles talle: Isa, ma olen pattu teinud taeva vastu ja sinu ees ega ole enam väärt, et mind su pojaks hüütaks!',
        22: 'Ent isa ütles oma sulastele: Tooge kõige kallim rüü ja pange temale selga ja andke temale sõrmus sõrme ja kingad jalga,',
        23: 'ja tooge, veristage nuumvasikas ja söögem ning olgem rõõmsad,',
        24: 'sest see mu poeg oli surnud ja on ellu virgunud, ta oli kadunud ja on leitud! Ja nemad hakkasid rõõmutsema.',
        25: 'Aga tema vanem poeg oli väljal; ja kui ta sealt tulles jõudis maja ligi, kuulis ta pilli ja ringmängu.',
        26: 'Siis ta kutsus ühe teenijaist enda juure ja kuulas, mis see peaks olema.',
        27: 'See ütles temale: Su vend on tulnud ja su isa on veristanud nuumvasika, et ta on saanud tema tervisega tagasi!',
        28: 'Aga ta vihastus ega tahtnud sisse minna. Siis tuli ta isa välja ja palus teda.',
        29: 'Kuid tema vastas ning ütles isale: Vaata, nii mitu aastat orjan mina sind ja ei ole iialgi astunud üle sinu käsu, ja sina ei ole mulle elades annud üht sikkugi, et ma oleksin võinud rõõmus olla oma sõpradega.',
        30: 'Aga kui tuli see sinu poeg, kes su vara on ära raisanud hooradega, veristasid sina temale nuumvasika!',
        31: 'Tema ütles temale: Laps, sina oled ikka minu juures ja kõik, mis on minu, on sinu!',
        32: 'Nüüd oli tarvis pidu teha ja rõõmutseda, et see sinu vend oli surnud ja on jälle saanud elavaks, ja et ta oli kadunud ja on leitud!"',
    },
    16: {
        1: 'Aga Ta ütles ka Oma jüngritele: "Oli keegi rikas mees, kellel oli majapidaja, ja seda oli tema ees süüdistatud, nagu pillaks see tema vara.',
        2: 'Ta kutsus tema ja ütles talle: Kuidas ma seda kuulen sinust? Tee aru oma majapidamisest, sest sa ei või enam maja pidada!',
        3: 'Aga majapidaja mõtles iseeneses: Mis ma teen? Minu isand võtab mu käest majapidamise ära; kaevata ma ei jaksa, kerjata on mul häbi.',
        4: 'Ma tean, mis ma teen, et kui ma majapidamisest lahti saan, mind vastu võetaks nende kodadesse.',
        5: 'Ja ta kutsus enda juure igaühe oma isanda võlglasist ja ütles esimesele: Palju sul on võlgu minu isandaga?',
        6: 'See ütles: Sada vaati õli! Tema ütles talle: Võta oma arveraamat, istu maha ning kirjuta kohe viiskümmend!',
        7: 'Pärast ta ütles teisele: Aga palju on sinul võlgu? Tema vastas: Sada vakka nisu! Ja ta ütles talle: Võta oma arveraamat ning kirjuta kaheksakümmend!',
        8: 'Ja isand kiitis seda ülekohtust majapidajat, et ta arukalt oli teinud, sest selle maailma lapsed on oma sugupõlve suhtes arukamad kui valguse lapsed.',
        9: 'Ja Mina ütlen teile: Tehke endile sõpru ülekohtuse mammonaga, et kui see saab otsa, nemad võtaksid teid vastu igavestesse telkidesse.',
        10: 'Kes ustav on kõige vähemas, see on ustav ka suures; ja kes ülekohtune on kõige vähemas, see on ülekohtune ka suures.',
        11: 'Kui te nüüd ülekohtuses mammonas ei ole ustavad olnud, kes võib teie kätte tõelist usaldada?',
        12: 'Ja kui te võõra omaga ei ole ustavad olnud, kes võib teile kätte anda meie oma?',
        13: 'Ükski sulane ei või teenida kaht isandat; sest kas ta vihkab üht ja armastab teist, või hoiab ühe poole ja põlgab teise ära; te ei või teenida Jumalat ja mammonat!"',
        14: 'Aga seda kõike kuulsid ka variserid, kes olid rahaahned; ja nad irvitasid Teda.',
        15: 'Ja Ta ütles neile: "Teie olete need, kes endid teevad õigeks inimeste ees; aga Jumal tunneb teie südant. Sest mis inimeste keskel on kõrge, see on Jumala ees jäledus.',
        16: 'Käsuõpetus ja prohvetid ulatavad Johanneseni; sellest ajast peale kuulutatakse Jumala Riiki ja igaüks tungib väevõimul sinna sisse.',
        17: 'Aga kergem on, et taevas ja maa hukka lähevad, kui et üks täheke käsuõpetusest hävib!',
        18: 'Igauks, kes oma naise enesest lahutab ja võtab teise, see rikub abielu; ja igaüks, kes võtab lahutatud naise, see rikub abielu.',
        19: 'Oli üks rikas mees. See riietus purpuri ja kalli lõuendiga ja elas iga päev rõõmsasti ja suuresti.',
        20: 'Aga üks vaene, Laatsarus nimi, oli maas tema värava ees täis paiseid',
        21: 'ja püüdis oma kõhtu täita leivaraasukestega, mis rikka laualt kukkusid. Ent koeradki tulid ja lakkusid tema paiseid.',
        22: 'Siis sündis, et vaene suri, ja Inglid kandsid ta Aabrahami sülle. Aga ka rikas suri ja maeti maha.',
        23: 'Ja kui ta põrgus suures valus oli ja oma silmad üles tõstis, nägi ta Aabrahami kaugelt ja Laatsarust tema süles.',
        24: 'Ja tema hüüdis ning ütles: Isa Aabraham, halasta mu peale ja läkita Laatsarus, et ta oma sõrme otsa kastaks vette ja jahutaks mu keelt, sest ma tunnen suurt piina selles tuleleegis!',
        25: 'Aga Aabraham ütles: Laps, mõtle, et sa oled hea põlve oma elus kätte saanud ja Laatsarus nõndasamuti kurja. Nüüd rõõmustatakse teda siin ja sina oled piinas.',
        26: 'Ja kõige selle lisaks on meie ja teie vahele seatud suur kuristik, et need, kes siit tahavad minna teie juure, ei saa mitte, ega need, kes seal on, ei saa tulla meie juure!',
        27: 'Aga ta ütles: Ma palun siis sind, isa, et sa läkitaksid tema mu isa majasse,',
        28: 'sest mul on viis venda - et ta kinnitaks neile, et nemadki ei satuks siia piinapaika!',
        29: 'Kuid Aabraham ütles: Neil on Mooses ja prohvetid; kuulaku nad neid!',
        30: 'Aga tema ütles: Ei mitte, isa Aabraham, vaid kui keegi surnuist läheks nende juure, siis nad parandaksid meelt!',
        31: 'Siis Aabraham ütles talle: Kui nad ei kuula Moosest ja prohveteid, ei nad veenduks ka, kui keegi surnuist üles tõuseks!"',
    },
    17: {
        1: 'Ja Ta ütles oma jüngritele: "Võimatu on, et pahandusi ei tuleks; aga häda sellele, kelle läbi need tulevad!',
        2: 'Sellele oleks tulusam, et veskikivi pandaks temale kaela ja ta visataks merre, kui et ta pahandaks ühe neist pisukesist.',
        3: 'Pidage endid silmas! Kui su vend pattu teeb, siis noomi teda; ja kui ta kahetseb, anna talle andeks.',
        4: 'Ja kui ta seitse korda päevas eksib su vastu ja seitse korda päevas pöördub su poole ning ütleb: Ma kahetsen! siis anna temale andeks!"',
        5: 'Ja Apostlid ütlesid Issandale: "Kasvata meie usku!"',
        6: 'Aga Issand ütles: "Kui teil usku oleks sinepiivakese võrra ja te ütleksite sellele metsviigipuule: Juuri end välja ja istuta end merre! siis see kuuleks teie sõna.',
        7: 'Aga kes teie seast, kellel sulane on kündmas või karja hoidmas, ütleks temale, kui ta põllult tuleb: Tule kohe siia ja istu lauda!?',
        8: 'Eks ta pigemini ütle temale: Valmista, mida ma õhtuks söön, ja pane vöö vööle ja talita mind, kuni ma saan söönud ja joonud; ja pärast seda söö ja joo sina.',
        9: 'Kas ta seda sulast tänab, et see tegi, mida kästi?',
        10: 'Nõnda ka teie: kui te olete kõik teinud, mis teid on kästud, siis ütelge: Me oleme kõlvatumad sulased; me oleme teinud, mis meie kohus oli teha!"',
        11: 'Ja sündis, kui Ta oli teel Jeruusalemma, et Ta läks Samaaria ja Galilea vahelt läbi.',
        12: 'Ja kui Ta saabus ühte alevisse, tulid Temale vastu kümme pidalitõbist meest ja jäid eemale seisma,',
        13: 'ja nad tõstsid häält ning ütlesid: "Jeesus, õpetaja, halasta meie peale!"',
        14: 'Neid nähes ütles ta neile: "Minge ja näidake endid preestritele!" Ja kui nad läksid, said nad puhtaks.',
        15: 'Aga üks nende seast, nähes enese terveks saanud olevat, läks tagasi ja andis Jumalale suure häälega au',
        16: 'ja heitis Tema jalge ette silmili maha ja tänas Teda. Ja see oli samaarlane.',
        17: 'Aga Jeesus kostis ning ütles: "Eks kümme ole saanud puhtaks? Ent kus on need üheksa?',
        18: 'Kas muid ei ole leitud, kes oleksid tulnud tagasi Jumalale au andma, kui aga see muulane?"',
        19: 'Ja Ta ütles temale: "Tõuse üles ja mine; su usk on sind aidanud!"',
        20: 'Aga kui variserid Temalt küsisid, millal tuleb Jumala Riik, vastas Ta neile ning ütles: "Jumala riik ei tule tähelepanu äratades;',
        21: 'ei ütelda ka mitte: Vaata siin! või: Vaata seal! sest ennäe, Jumala Riik on seespidi teie sees!"',
        22: 'Ja Ta ütles jüngritele: "Päevad tulevad, mil te himustate näha üht Inimese Poja päevist, ja te ei näe mitte!',
        23: 'Siis üteldakse teile: Vaata siin! või: Vaata seal! Ärge minge ja ärge ajage seda taga!',
        24: 'Sest otsegu välk, mis sähvatab teisel pool taeva serval ja paistab teisele poole taeva servale, nõnda on Inimese Poeg Omal päeval!',
        25: 'Kuid enne Ta peab palju kannatama ja sellesinase sugupõlve poolt kõlbmatuna ära heidetama.',
        26: 'Ja nõnda nagu oli Noa päevil, nõnda on ka Inimese Poja päevil:',
        27: 'nad sõid, jõid, võtsid naisi ja läksid mehele selle päevani, mil Noa läks laeva, ja tuli veeuputus ning hävitas nad kõik.',
        28: 'Samuti ka, nagu oli Loti päevil: nad sõid, jõid, ostsid, müüsid, istutasid, ehitasid hooneid;',
        29: 'aga sel päeval, mil Lott väljus Soodomast, sadas tuld ja väävlit taevast ning hävitas nad kõik.',
        30: 'Otse nii peab olema sel päeval, mil Inimese Poeg ilmub!',
        31: 'Kes sel päeval on katusel ja kelle riistad on toas, ärgu see tulgu maha neid võtma; ja nõndasamuti, kes on põllul, ärgu mingu koju tagasi.',
        32: 'Mõtelge Loti naisele!',
        33: 'Kes oma hinge püüab säästa, see kaotab selle, ja kes selle kaotab, see hoiab selle elus!',
        34: 'Ma ütlen teile, selsamal ööl on kaks ühes voodis: üks võetakse vastu ja teine jäetakse maha;',
        35: 'kaks naist jahvatavad üheskoos: üks võetakse vastu ja teine jäetakse maha;',
        36: 'kaks meest on väljal: üks võetakse vastu ja teine jäetakse maha!"',
        37: 'Ja nad vastasid ning ütlesid Temale: "Kus, Issand?" Aga Ta ütles neile: "Kus on korjus, sinna kogunevad ka kotkad!"',
    },
    18: {
        1: 'Aga ta ütles neile tähendamissõna, selleks et alati tuleks palvetada ja mitte tüdida.',
        2: 'Ta ütles: "Ühes linnas oli kohtunik, kes ei kartnud Jumalat ega häbenenud inimesi.',
        3: 'Samas linnas oli ka lesknaine. See tuli ta juure ja ütles: Kaitse mu õigust mu vastase vastu!',
        4: 'Ja kaua aega ta ei tahtnud. Kuid pärast ta mõtles iseeneses: Ehk ma küll Jumalat ei karda ja inimesi ei häbene,',
        5: 'siis ometigi, kuna see lesk mind tüütab, muretsen ma temale õiguse, et ta viimaks ei tuleks ja mulle näkku ei lööks!"',
        6: 'Siis ütles Issand: "Kuulge, mida see ülekohtune kohtunik ütleb!',
        7: 'Kas siis Jumal ei peaks muretsema õigust oma äravalituile, kes Tema poole kisendavad ööd ja päevad, ja kas Ta peaks viivitama neid aidates?',
        8: 'Ma ütlen teile: Küll ta peatselt muretseb neile õiguse! Siiski, kui Inimese Poeg tuleb, kas Ta leiab usku maa pealt?"',
        9: 'Aga ka mõnede vastu, kes iseeneste peale lootsid, et nad on õiged, ja põlgasid muid, ütles Ta selle tähendamissõna:',
        10: '"Kaks inimest läks üles pühakotta palvetama: üks oli variser ja teine tölner.',
        11: 'Variser seisis ning palus iseeneses nõnda: Oh Jumal, ma tänan Sind, et mina ei ole nõnda nagu muud inimesed, röövijad, ülekohtused, abielurikkujad ega nõnda nagu see tölner!',
        12: 'Ma paastun kaks korda nädalas; ma annan kümnist kõigest, mis saan!',
        13: 'Aga tölner seisis eemal ega tahtnud oma silmigi tõsta taeva poole, vaid lõi enesele vastu rindu ning ütles: Oh Jumal, ole mulle patusele armuline!',
        14: 'Ma ütlen teile, et see läks alla oma kotta paremini õigeks mõistetuna kui teine! Sest igaüht, kes ennast ise ülendab, alandatakse; aga kes ennast ise alandab, seda ülendatakse!"',
        15: 'Siis toodi ka lapsukesi Tema juure, et Ta neid puudutaks. Aga seda nähes jüngrid sõitlesid toojaid.',
        16: 'Ent kuuljad ütlesid: "Kes siis võib õndsaks saada?"',
        17: 'Tõesti, Ma ütlen teile, kes Jumala Riiki vastu ei võta nagu lapsuke, see ei pääse sinna sisse!"',
        18: 'Ja üks ülem küsis Temalt ning ütles: "Hea Õpetaja, mis ma pean tegema, et ma igavese elu päriksin?"',
        19: 'Aga Jeesus ütles temale: "Miks sa Mind nimetad heaks? Keegi muu ei ole hea kui ainult Jumal.',
        20: 'Käsud sa tead: Sa ei tohi abielu rikkuda; sa ei tohi tappa; sa ei tohi varastada; sa ei tohi valet tunnistada; sa pead oma isa ja ema austama!"',
        21: 'Aga tema ütles: "Seda kõike ma olen pidanud oma noorestpõlvest alates!"',
        22: 'Aga kui Jeesus seda kuulis, ütles Ta temale: "Üht asja on sulle vaja: müü ära kõik, mis sul on, ja jaga vaestele, ja sul on siis varandus taevas; ja tule ning järgi Mind!"',
        23: 'Aga seda kuuldes sai ta koguni kurvaks; sest ta oli väga rikas.',
        24: 'Teda nõnda nähes, ütles Jeesus: "Kui raske on jõukail sisse minna Jumala Riiki!',
        25: 'Sest hõlpsam on, et kaamel läheb läbi nõelasilma, kui et rikas sisse läheb Jumala Riiki!"',
        27: 'Aga Tema ütles: "Mis inimestel on võimatu, on Jumalal võimalik!"',
        28: 'Siis ütles Peetrus: "Vaata, meie oleme kõigest loobunud ja oleme Sind järginud!"',
        29: 'Aga Tema ütles neile: "Tõesti, Ma ütlen teile, et ei ole kedagi, kes on loobunud majast või naisest või vendadest või vanemaist või lapsist Jumala Riigi pärast,',
        30: 'kes mitte mitu korda rohkem tagasi ei saaks selsinasel ajal ja tulevases maailmas igavest elu!"',
        31: 'Aga Ta võttis need kaksteistkümmend Enese juure ja ütles neile: "Vaata, me läheme üles Jeruusalemma ja kõik viiakse lõpule, mis prohvetid on kirjutanud Inimese Pojast!',
        32: 'Sest Ta antakse ära paganate kätte ja Teda naerdakse ja teotatakse ja Tema peale sülitatakse,',
        33: 'ja kui nad Teda on rooskadega peksnud, tapavad nad Ta, ja kolmandal päeval Ta tõuseb üles!"',
        34: 'Aga nemad ei saanud midagi aru sellest, ja see kõne oli varjul nende eest, ja nad ei mõistnud, mida üteldi.',
        35: 'Aga kui Ta Jeerikole lähenes, istus üks pime tee ääres ja kerjas.',
        36: 'Kuuldes rahvast mööda minevat, päris ta, mis see peaks olema.',
        37: 'Talle teatati: "Jeesus Naatsaretlane läheb mööda!"',
        38: 'Siis ta kisendas ning ütles: "Jeesus, Taaveti Poeg, halasta mu peale!"',
        39: 'Ja möödaminejad sõitlesid teda, et ta vait jääks. Tema aga karjus palju rohkem: "Taaveti Poeg, halasta minu peale!"',
        40: 'Jeesus jäi seisma ja käskis talutada teda Enese juure. Kui ta ligidale jõudis, küsis Ta temalt:',
        41: '"Mis sa tahad, et Ma sulle teeksin?" Tema ütles: "Issand, et ma jälle näeksin!"',
        42: 'Ja Jeesus ütles temale: "Näe jälle! Sinu usk on sind aidanud!"',
        43: 'Ja kohe ta nägi jälle ja järgis Teda ning andis Jumalale au! Ja seda nähes kõik rahvas kiitis Jumalat!',
    },
    19: {
        1: 'Ja tema tuli Jeeriko linna ja läks sealt läbi.',
        2: 'Ja vaata, seal oli mees, Sakkeus nimi, ja see oli tölnerite ülem ja oli rikas.',
        3: 'Ja ta püüdis näha saada Jeesust, kes Ta on, aga ei saanud rahva pärast, sest ta oli väikese kasvuga.',
        4: 'Ja ta jooksis ettepoole ja ronis metsviigipuu otsa, et Teda näha; sest Jeesus pidi sealtkaudu minema.',
        5: 'Kui nüüd Jeesus sinna paika jõudis, vaatas Ta üles ja nägi teda ning ütles temale: "Sakkeus, tule usinasti maha, sest täna Ma pean jääma sinu kotta!"',
        6: 'Ja ta tuli usinasti maha ja võttis Teda vastu rõõmuga.',
        7: 'Seda nähes nurisesid kõik ning ütlesid: "Tema on ühe patuse mehe juure läinud jalgu puhkama!"',
        8: 'Aga Sakkeus astus Issanda ette ning ütles: "Vaata, Issand, poole oma varandusest ma annan vaestele; ja kui ma kellelegi olen ülekohut teinud, annan ma neljakordselt tagasi!"',
        9: 'Siis Jeesus ütles temale: "Täna on sellele kojale õnnistus tulnud, sest ka tema on Aabrahami poeg;',
        10: 'sest Inimese Poeg on tulnud otsima ja päästma, mis on kadunud!"',
        11: 'Aga kui nad seda kuulsid, ütles Ta sinna juure veel tähendamissõna, sellepärast et Ta oli Jeruusalema lähedal ja et nemad arvasid Jumala Riigi varsti ilmuvat.',
        12: 'Sellepärast Ta ütles: "Üks suursugune inimene läks teele kaugele maale, et omandada kuningriik ja tulla tagasi.',
        13: 'Aga ta kutsus oma kümme sulast ja andis neile kümme naela raha ning ütles neile: Kaubelge seni, kuni ma tagasi tulen.',
        14: 'Aga tema kodanikud vihkasid teda ja läkitasid käskjalad temale järele ja lasksid ütelda: Me ei taha, et ta on kuningaks meie üle!',
        15: 'Ja sündis, kui tema tuli tagasi ja oli omandanud selle riigi, et ta käskis kutsuda enese juure need sulased, kelledele ta raha oli annud, et teada saada, missugust kasu igaüks kaubeldes oli saavutanud.',
        16: 'Siis tuli sinna esimene ja ütles: Isand, sinu nael raha on tootnud kümme naela!',
        17: 'Tema ütles talle: See on hea, sa hea sulane! Et sa kõige vähemas oled ustav olnud, siis olgu sul valitsus kümne linna üle!',
        18: 'Ja teine tuli ja ütles: Isand, sinu nael on tootnud viis naela!',
        19: 'Aga ta ütles sellelegi: Ja sina valitse viie linna üle!',
        20: 'Veelgi tuli teine ja ütles: Isand, vaata, siin on su nael, mida ma olen hoidnud higirätikus;',
        21: 'sest ma kartsin sind, et sa oled vali inimene; sa võtad, mida sa ei ole paigale pannud, ja lõikad, mida sa ei ole külvanud!',
        22: 'Ta ütles temale: Sinu suust ma mõistan sind hukka, sa paha sulane! Kui sa teadsid, et ma olen vali mees ja võtan, mida ma ei ole pannud paigale, ja lõikan, mida ma ei ole külvanud,',
        23: 'miks sa siis ei annud mu raha panka? Küll ma tulles oleksin selle tagasi nõudnud kasudega.',
        24: 'Ja ta ütles juuresseisjaile: Võtke nael ära ta käest ja andke sellele, kellel on kümme!',
        25: 'Ja nad ütlesid talle: Isand, temal on kümme naela!',
        26: 'Ma ütlen teile: Kellel on, sellele antakse, aga kellel ei ole, sellelt võetakse ka see, mis tal on!',
        27: 'Aga need mu vaenlased, kes ei tahtnud mind kuningaks, tooge tänna ja tapke nad ära minu ees!"',
        28: 'Ja kui ta seda oli rääkinud, läks ta edasi Jeruusalema poole.',
        29: 'Ja sündis, kui Ta Betfage ja Betaania ligi jõudis, mäe juure, mida kutsutakse Õlimäeks, et Ta läkitas kaks Oma jüngrit',
        30: 'ning ütles: "Minge vastasolevasse alevisse, ja kui te sinna jõuate, leiate te kinniseotud sälu, kelle seljas ükski inimene ei ole istunud. Päästke ta lahti ja tooge siia.',
        31: 'Ja kui keegi teilt küsib: Miks te ta lahti päästate? siis ütelge nii: Issandal on teda tarvis!"',
        32: 'Aga need, kes olid läkitatud, läksid ja leidsid kõik nõnda, nagu Ta neile oli ütelnud. 33 Kui nad sälgu lahti päästsid, ütlesid selle omanikud neile: "Miks te sälu lahti päästate?"',
        34: 'Nemad vastasid: "Issandal on teda tarvis!"',
        35: 'Ja nad tõid selle Jeesuse juure, heitsid oma riided sälu peale ja panid Jeesuse tema selga istuma.',
        36: 'Kui Ta nüüd edasi liikus, laotasid nad oma riided tee peale.',
        37: 'Aga kui Ta lähenes Õlimäe kallakule, hakkas kogu jüngrite hulk rõõmutsedes suure häälega kiitma Jumalat kõigi vägevate tegude eest, mis nad olid näinud,',
        38: 'ning ütlesid: "Kiidetud olgu Kuningas, Kes tuleb Issanda nimel, rahu taevas ja au kõrges!"',
        39: 'Ja mõningad variserid rahva seast ütlesid Temale: "Õpetaja, sõitle Oma jüngreid!"',
        40: 'Ta vastas ning ütles: "Ma ütlen teile, kui need vait jääksid, hakkaksid kivid kisendama!"',
        41: 'Ja kui ta ligi jõudis ja linna nägi, nuttis Ta tema pärast',
        42: 'ning ütles: "Kui sina teaksid sellel päeval, mis sinu rahule tarvis läheb! Ent nüüd see on pandud varjule sinu silmade eest.',
        43: 'Sest päevad tulevad sinu peale, mil su vaenlased teevad sinu ümber valli ja piiravad sind ja vaevavad sind kõikepidi.',
        44: 'Ja lõhuvad sind maha maatasa ja su lapsed sinu sees ega jäta kivi kivi peale, sellepärast et sa ei ole tunnud oma armukatsumisaega!"',
        45: 'Ja Ta läks pühakotta ja hakkas välja ajama neid, kes seal müüsid ja ostsid,',
        46: 'ning ütles neile: "Kirjutatud on: Minu koda on palvekoda, aga teie olete ta teinud röövliauguks!"',
        47: 'Ja Ta oli iga päev õpetamas pühakojas; aga ülempreestrid ja kirjatundjad ja rahvaülemad püüdsid Teda hukka saata,',
        48: 'kuid ei leidnud, mis teha. Sest kõik rahvas rippus Ta küljes Teda kuulates.',
    },
    20: {
        1: 'Ja ühel päeval, kui Ta pühakojas rahvast õpetas ja Evangeeliumi kuulutas, tulid ülempreestrid ja kirjatundjad vanematega Ta juure,',
        2: 'kõnetasid Teda ning ütlesid: "Ütle meile, missuguse meelevallaga Sa teed seda või kes on see, kes Sulle selle meelevalla on annud?"',
        3: 'Tema kostis ning ütles neile: "Mina küsin ka teilt ühe asja; ütelge Mulle:',
        4: 'Kas oli Johannese ristimine taevast või inimestest?"',
        5: 'Nemad pidasid nõu isekeskis, üteldes: "Kui me ütleme taevast, siis Ta ütleb: Mispärast te ei ole siis teda uskunud?',
        6: 'Aga kui me ütleme inimestest, siis kõik rahvas viskab meid kividega, sest see on veendunud, et Johannes on prohvet!"',
        7: 'Nemad vastasid, et nad ei teadvat, kust.',
        8: 'Siis Jeesus ütles neile: "Ega Minagi ütle teile, missuguse meelevallaga Ma seda teen!"',
        9: 'Aga Ta hakkas rääkima rahvale seda tähendamissõna: "Üks inimene istutas viinamäe ja andis selle rendile aednike kätte ning läks välismaale kauaks ajaks.',
        10: 'Ja parajal ajal ta läkitas sulase aednike juure, et nad temale annaksid viinamäe viljast. Aga aednikud peksid teda ja saatsid ta tühjalt minema.',
        11: 'Ja ta läkitas veel teise sulase. Aga nad peksid tedagi ja saatsid ta tühjalt minema.',
        12: 'Ja ta läkitas veel kolmanda. Aga nad haavasid ka seda ja tõukasid ta välja.',
        13: 'Siis ütles viinamäe isand: Mis ma pean tegema? Ma läkitan oma armsa poja, vahest nad häbenevad teda!',
        14: 'Aga kui aednikud teda nägid, pidasid nad nõu isekeskis ning ütlesid: See on pärija. Tapame ta ära, et pärand saaks meile!',
        15: 'Ja nad tõukasid ta viinamäest välja ja tapsid ta ära. Mis teeb nüüd viinamäe isand nendega?',
        16: 'Ta tuleb ja hukkab need aednikud ja annab viinamäe teiste kätte!" Seda kuuldes nad ütlesid: "Ärgu seda sündigu!"',
        17: 'Aga Tema vaatas neile otsa ja ütles: "Mis see siis õigupoolest tähendab, mis on kirjutatud: See kivi, mille hooneehitajad kui kõlbmatu ära heitsid, see on saanud nurgakiviks!',
        18: 'Igaüks, kes selle kivi peale kukub, läheb rusuks; aga kelle peale see langeb, selle ta teeb pihuks!"',
        19: 'Ja ülempreestrid ja kirjatundjad püüdsid selsamal tunnil pista käed Tema külge, kuid nad kartsid rahvast, sest nad said aru, et Ta nende kohta oli ütelnud selle tähendamissõna.',
        20: 'Ja nad varitsesid Teda ja läkitasid välja kavalad mehed, kes pidid teesklema õigeid, et Teda tabada kõnest ja Teda ära anda ülemusele ning maavalitseja meelevalda.',
        21: 'Ja nad küsisid Temalt ning ütlesid: "Õpetaja, me teame, et Sa räägid ja õpetad õigesti ega arvesta ühegi isikut, vaid õpetad Jumala teed tõtt mööda.',
        22: 'Kas meil sünnib keisrile anda maksuraha või ei sünni?"',
        23: 'Aga Tema mõistis ära nende kurikavaluse ja ütles neile: "Miks te Mind kiusate?',
        24: 'Näidake Mulle teenariraha! Kelle kuju ja pealkiri sellel on?" Nemad vastasid: "Keisri!"',
        25: 'Tema ütles neile: "Siis andke keisrile, mis kuulub keisrile, ja Jumalale, mis kuulub Jumalale!"',
        26: 'Ja nad ei saanud Teda kinni võtta rahva ees; ja imestades Tema vastust, jäid nad vait.',
        27: 'Ent Ta juure tuli mõningaid sadusere, kes ütlesid, et ei ole ülestõusmist, ja küsisid Temalt',
        28: 'nõnda: "Õpetaja, Mooses on meile kirjutanud, et kui kellegi vend, kes oli naisemees, sureb ja tal ei olnud lapsi, siis võtku ta vend selle naine ja saatku oma vennale sugu.',
        29: 'Oli kord seitse venda; ja esimene võttis naise ja suri lapseta.',
        30: 'Ja teine samuti.',
        31: 'Ja kolmas võttis tema, ja nõndasamuti ka kõik seitse ei jätnud lapsi järele ja surid.',
        32: 'Kõige viimaks suri ka naine.',
        33: 'Kelle naiseks nende seast nüüd see naine peab olema ülestõusmises? Ta on ju olnud naiseks neile seitsmele?"',
        34: 'Jeesus kostis neile: "Sellesinase maailm-asjastu lapsed võtavad naisi ja lähevad mehele,',
        35: 'aga kes on väärt arvatud jõudma teise maailma ja surnuist üles tõusma, ei need võta naist ega lähe mehele.',
        36: 'Sest nad ei või ka enam surra; nad on Inglite sarnased ja nad on Jumala pojad, olles ülestõusmise pojad.',
        37: 'Aga et surnud tõusevad üles, seda näitab ka Mooses kibuvitsapõõsa loos, kui ta nimetab Issandat Aabrahami Jumalaks ja Iisaki Jumalaks ja Jaakobi Jumalaks;',
        38: 'Jumal aga ei ole mitte surnute, vaid on elavate Jumal; sest kõik elavad Temale!"',
        39: 'Siis mõned kirjatundjaist vastasid ning ütlesid: "Õpetaja, Sa oled hästi rääkinud!"',
        40: 'Ei nad julgenud Temalt ka enam midagi küsida.',
        41: 'Aga Ta ütles neile: "Kuidas üteldakse Kristus olevat Taaveti Poeg,',
        42: 'kuna Taavet ise ütleb Laulude raamatus: Issand on ütelnud minu Issandale: Istu Mu paremale poole,',
        43: 'kuni Ma panen Su vaenlased Su jalgealuseks järiks?',
        44: 'Taavet nimetab siis Teda Issandaks, ja kuidas Ta on tema Poeg?"',
        45: 'Aga Ta ütles kõige rahva kuuldes Oma jüngritele:',
        46: '"Hoiduge kirjatundjate eest, kes tahavad käia pikis rüüdes ja armastavad teretusi turgudel ja esimesi istmeid kogudusekodades ja ülemat kohta lauas söömaaegadel!',
        47: 'Nemad söövad leskede hooned ja loevad silmakirjaks pikki palveid. Need saavad seda raskema hukatuse!"',
    },
    21: {
        1: 'Aga Ta vaatas ja nägi rikkaid oma ande ohvrikirstu panevat.',
        2: 'Ent Ta nägi ka üht vaest lesknaist kaks leptonit sinna sisse panevat.',
        3: 'Ja Ta ütles: "Tõesti Ma ütlen teile, see vaene lesknaine pani rohkem kui kõik muud!',
        4: 'Sest need kõik panid oma küllusest anni, kuid tema pani oma vaesusest kõik toiduse, mis tal oli!"',
        5: 'Ja kui mõningad rääkisid pühakojast, et see on ilusate kividega ja annetistega ehitud, ütles Ta:',
        6: '"Päevad tulevad, et sellest kõigest, mida te näete, ei jäeta kivi kivi peale, mida maha ei kistaks!"',
        7: 'Siis küsiti Temalt: "Õpetaja, millal see siis sünnib? Ja mis on selle tunnuseks, et see hakkab sündima?"',
        8: 'Aga Tema ütles: "Katsuge, et teid ei eksitataks; sest paljud tulevad Minu nime all ja ütlevad: Mina olen see! ja: Aeg on lähenenud! Ärge minge nende järele!',
        9: 'Ja kui te kuulete sõdadest ja mässudest, siis ärge kohkuge; sest see peab enne sündima; aga ots ei ole veel niipea käes!"',
        10: 'Siis ta ütles neile: "Rahvas tõuseb rahva vastu ja kuningriik kuningriigi vastu',
        11: 'ja suuri maavärisemisi on siis ja paiguti nälga ning katku; ja hirmsaid asju on näha ning suuri tunnustähti taeval!',
        12: 'Aga enne kõike seda pistavad nad oma käed teie külge ja kiusavad teid taga, andes teid ära kogudusekodadesse ja vangi, viivad teid kuningate ja maavalitsejate ette Minu nime pärast.',
        13: 'Aga see annab teile juhust tunnistamiseks.',
        14: 'Seepärast võtke südamesse, et te enneaegu ei muretseks, mida vastata enda kaitseks.',
        15: 'Sest Mina annan teile suu ja tarkuse, mille vastu ei saa panna ega rääkida ükski teie vastaseist.',
        16: 'Ka teie vanemad ja vennad ja sugulased ning sõbrad annavad teid ära ja surmavad mõned teie seast;',
        17: 'ja teid vihatakse kõikide poolt Minu nime pärast.',
        18: 'Aga mitte juuksekarvgi ei saa hukka teie peast!',
        19: 'Oma püsivusega kannatustes te päästate oma hinged.',
        20: 'Aga kui te näete Jeruusalma olevat sõjaväe poolt ümber piiratud, siis tundke, et ta hävitus on ligidal!',
        21: 'Siis põgenegu need, kes on Juudamaal, mägedele ja need, kes on linnas, mingu välja, ja kes on maal, ärgu mingu linna.',
        22: 'Sest need on kättemaksu päevad, et läheks täide, mis on kirjutatud.',
        23: 'Häda käima peal olijaile ja imetajaile neil päevil, sest suur häda on maa peal ja viha selle rahva vastu!',
        24: 'Ja nad langevad mõõgatera läbi ja nad viiakse vangi kõigi rahvaste sekka, ja Jeruusalem jääb paganrahvaste tallata, kuni paganate ajad täis saavad.',
        25: 'Ja päikeses, kuus ja tähtedes on ennustusmärke ja maa peal on rahvastel ahastus ja nõutu olek mere kohina ja veevoogude pärast.',
        26: 'Ja inimesed lähevad rammetumaks kartuse ja sündmuste ootamise pärast, mis maailma peale on tulemas; sest taeva vägesid kõigutatakse.',
        27: 'Ja siis nad näevad Inimese Poja tulevat pilves suure väe ja auhiilgusega!',
        28: 'Aga kui see kõik hakkab sündima, siis vaadake üles ja tõstke oma pead, sest teie lunastus läheneb!"',
        29: 'Ja Ta ütles neile võrdumi: "Vaadake viigipuud ja kõiki puid!',
        30: 'Kui nad juba pakatavad ja te näete seda, siis tunnete iseenesest, et suvi on juba ligidal.',
        31: 'Nõnda ka teie: kui te näete seda sündivat, siis tundke, et Jumala Riik on ligidal!',
        32: 'Tõesti Ma ütlen teile, see sugupõlv ei lõpe ära, enne kui see kõik sünnib!',
        33: 'Taevas ja maa hävivad, kuid Minu sõnad ei hävi mitte!',
        34: 'Aga hoidke, et te oma südameid ei koormaks liigsöömise ega purjutamisega ega peatoiduse muredega ja et see päev ei tuleks teie peale äkitselt',
        35: 'otsegu linnupael! Sest ta tuleb kõikide peale, kes kogu maapinnal asuvad!',
        36: 'Siis valvake ja paluge igal ajal, et teid arvataks väärt põgenema kõige selle eest, mis tuleb, ja seisma Inimese Poja ees!"',
        37: 'Ja Ta õpetas päeva ajal pühakojas, aga ööseks Ta läks välja ning ööbis mäel, mida kutsutakse Õlimäeks.',
        38: 'Ja kõik rahvas tuli vara hommikul Tema juure pühakotta Teda kuulama.',
    },
    22: {
        1: 'Aga hapnemata leibade päev, mida kutsutakse paasapühaks, oli ligidal.',
        2: 'Ja ülempreestrid ja kirjatundjad pidasid aru, kuidas Teda surmata; sest nad kartsid rahvast.',
        3: 'Aga saatan oli läinud Juudase sisse, keda liignimega hüüti Iskariotiks, kes oli nende kaheteistkümne arvust.',
        4: 'Ja ta läks ära ja rääkis ülempreestrite ja sõjapealikutega, kuidas ta võiks Tema ära anda nende kätte.',
        5: 'Ja nad said rõõmsaks ja leppisid kokku, et nad annavad temale raha.',
        6: 'Tema nõustus sellega ja otsis parajat juhust Tema äraandmiseks neile ilma rahva teadmata.',
        7: 'Nii jõudis kätte hapnemata leibade päev, mil paasatall pidi tapetama.',
        8: 'Ja Ta läkitas Peetruse ja Johannese ning ütles: "Minge ja valmistage meile paasatall, et me seda sööksime."',
        9: 'Aga nad küsisid Temalt: "Kus Sa tahad, et me selle valmistame?"',
        10: 'Tema vastas neile: "Vaata, kui te linna sisse lähete, siis tuleb teile vastu inimene, kes kannab veekruusi; minge Tema järele sinna majasse, kuhu Ta sisse läheb,',
        11: 'ja ütelge selle maja isandale: Õpetaja ütleb sulle: Kus on võõrastetuba, kus Ma võiksin süüa paasatalle Oma jüngritega?',
        12: 'Siis ta näitab teile suure ülemise toa; seal valmistage."',
        13: 'Ent kui nad ära läksid, leidsid nad nõnda, nagu Ta neile oli ütelnud. Ja nad valmistasid paasatalle.',
        14: 'Ja kui tund kätte jõudis, istus Ta maha ja Apostlid ühes Temaga.',
        15: 'Ja Ta ütles neile: "Ma olen südamest igatsenud seda paasatalle süüa ühes teiega, enne kui Ma kannatan.',
        16: 'Sest Ma ütlen teile, et Ma ei söö enam sellest, kuni kõik on täide läinud Jumala Riigis!"',
        17: 'Ja Ta võttis karika, tänas ning ütles: "Võtke see ja jagage eneste vahel.',
        18: 'Sest Ma ütlen teile, et Mina ei joo enam viinapuu viljast, enne kui tuleb Jumala Riik!"',
        19: 'Ja Ta võttis leiva, tänas ja murdis ja andis neile ning ütles: "See on Minu ihu, mis teie eest antakse; seda tehke Minu mälestuseks!"',
        20: 'Samuti ka karika pärast õhtusöömaaega ja ütles: "See karikas on Uus Leping Minu veres, mis teie eest valatakse.',
        21: 'vaata, Mu äraandja käsi on Minuga lauas!',
        22: 'Ja Inimese Poeg läheb küll ära, nõnda nagu see on määratud; ometi häda sellele inimesele, kes Ta ära annab!"',
        23: 'Ja nemad hakkasid küsima üksteiselt, kes see küll peaks nende seast olema, kes seda teeb.',
        24: 'Aga nende seas tõusis vaidlus ka selle kohta, keda neist tuleks arvata suuremaks.',
        25: 'Siis Tema ütles neile: "Rahvaste kuningad valitsevad isandaina nende üle ja nende võimumehi hüütakse armulisiks isandaiks.',
        26: 'Kuid teie ärge olge nõnda, vaid suurem teie seast olgu nagu noorem, ja ülem nõnda nagu see, kes teenib.',
        27: 'Sest kumb on suurem, kas see, kes istub lauas, või see, kes teenib? Eks see, kes istub lauas? Ent Mina olen teie seas nõnda nagu see, kes teenib.',
        28: 'Aga teie olete need, kes Minu juure on jäänud Mu kiusatustes;',
        29: 'ja Mina sean teile Riigi, nõnda nagu Minu Isa selle Mulle on seadnud,',
        30: 'et te sööksite ja jooksite Minu lauas Minu Riigis ja istuksite aujärgedel ja mõistaksite kohut Iisraeli kaheteistkümne suguharu üle!"',
        31: '"Siimon, Siimon, vaata, saatan on väga püüdnud sõeluda teid nagu nisu!',
        32: 'Aga Mina olen sinu eest palunud, et su usk ära ei lõpeks, ja kui sa pärast pöördud, siis kinnita oma vendi!"',
        33: 'Aga tema ütles Talle: "Issand, ma olen valmis Sinuga minema niihästi vangi kui surma!"',
        34: 'Kuid Ta ütles: "Ma ütlen sulle, Peetrus: kukk ei laula täna mitte enne, kui sina oled kolm korda salanud, et sa Mind tunned!"',
        35: 'Ja Ta ütles neile: "Kui Ma teid läkitasin kukruta ja paunata ja jalatseita, kas oli teil midagi puudu?" Nemad vastasid: "Ei midagi!"',
        36: 'Siis ta ütles neile: "Aga nüüd, kellel on kukkur, see võtku ta kaasa, nõndasamuti ka paun; ja kellel ei ole, see müügu ära oma kuub ja ostku mõõk!',
        37: 'Sest Ma ütlen teile, et Minus peab veel täide minema, mis on kirjutatud: "Ja Teda arvati üleastujate hulka!" Sest mis Minusse puutub, jõuab lõpule!"',
        38: 'Aga nemad ütlesid: "Issand, ennäe, siin on kaks mõõka!" Tema ütles neile: "Sellest jätkub!"',
        39: 'Ja Ta läks välja ja tuli Oma viisi järele Õlimäele. Ent ka Tema jüngrid järgisid Teda.',
        40: 'Ja kui ta jõudis kohale, ütles Ta neile: "Palvetage, et te ei satuks kiusatusse!"',
        41: 'Ta ise läks neist eemale, niikaugele kui kiviga jõuab visata, heitis põlvili maha ja palvetas,',
        42: 'üteldes: "Isa, kui Sa tahad, siis võta see karikas Minult ära; ometi ärgu sündigu Minu, vaid Sinu tahtmine!"',
        43: 'Siis ilmus Temale Ingel taevast ja kinnitas Teda.',
        44: 'Ja heideldes raskesti, palvetas Ta veel pinevamalt; ja Tema higi oli nagu verepisarad, mis langesid maa peale.',
        45: 'Ja Ta tõusis üles palvetamast ning tuli Oma jüngrite juure ja leidis nad magamast kurbuse pärast.',
        46: 'Ja Ta ütles neile: "Miks te magate? Tõuske üles ja palvetage, et te ei satuks kiusatusse!"',
        47: 'Kui Tema alles rääkis, vaata, siis tuli rahvast ja see, keda hüüti Juudaseks, üks neist kaheteistkümnest, käis nende ees ja tuli Jeesuse ligi teda suudlema.',
        48: 'Aga Jeesus ütles temale: "Juudas, annad sa Inimese Poja suudlusega ära?"',
        49: 'Kui nüüd kaaslased seda nägid, mis oli tulemas, ütlesid nad: "Issand, kas me peame mõõgaga sekka lööma?"',
        50: 'Ja üks neist lõi ülempreestri sulast ning raius tema parema kõrva ära.',
        51: 'Aga Jeesus kostis ning ütles: "Jätke sellega!" Ja Ta puudutas tema kõrva ja tegi ta terveks.',
        52: 'Siis Jeesus ütles ülempreestritele ja pühakoja pealikuile ja vanemaile, kes Tema vastu olid tulnud: "Te olete tulnud välja otsegu röövli vastu mõõkade ja nuiadega!',
        53: 'Kui Ma iga päev teie juures olin pühakojas, ei ole te pistnud käsi Mu külge. Ent see on teie tund ja pimeduse võimus!"',
        54: 'Aga nad võtsid Ta kinni ja viisid ning tõid Tema ülempreestri kotta. Aga Peetrus järgis Teda kaugelt.',
        55: 'Ja kui nad keset õue süütasid tule ja üheskoos maha istusid, istus ka Peetrus nende keskele.',
        56: 'Siis nägi üks ümmardaja teda tule ääres istuvat ning jäi temale otsa vaatama ja ütles: "Ka seesinane oli ühes Temaga!"',
        57: 'Aga tema salgas ning ütles: "Naine, mina Teda ei tunne!"',
        58: 'Üürikese aja pärast nägi teda teine, keegi mees, ning ütles: "Sinagi oled nende seast!" Kuid Peetrus ütles: "Inimene, mina ei ole mitte!"',
        59: 'Ja umbes tund aega hiljemini kinnitas seda keegi teine ning ütles: "Tõepoolest, seesinane oli Temaga, sest tema on ju galilealane!"',
        60: 'Aga Peetrus ütles: "Inimene, ma ei mõista, mida sa räägid!" Ja sedamaid laulis kukk!',
        61: 'Ja Issand pöördus ja vaatas Peetrusele; ja Peetrusele tuli meele Issanda sõna, kuidas Ta temale oli ütelnud: "Enne kui kukk täna laulab, salgad sa Mind kolm korda!"',
        62: 'Ja ta läks välja ja nuttis kibedasti.',
        63: 'Aga mehed, kes Jeesust kinni hoidsid, naersid ja peksid Teda,',
        64: 'ja nad katsid Ta silmad kinni ja küsisid Temalt ning ütlesid: "Mõista kui prohvet, kes see on, kes Sind lõi!"',
        65: 'Ja palju muid pilkesõnu nad rääkisid Tema vastu.',
        66: 'Ja kui valgeks läks, tulid rahvavanemad, ülempreestrid ja kirjatundjad kokku ja viisid Ta üles oma Suurkohtu ette',
        67: 'ning ütlesid: "Kui Sina oled Kristus, siis ütle meile!" Tema vastas neile: "Kui Ma teile ütlen, ei usu te ju mitte,',
        68: 'ja kui Ma küsin, ei vasta te mitte!',
        69: 'Ent nüüdsest peale hakkab Inimese Poeg istuma Jumala väe paremal poolel!"',
        70: 'Aga nad kõik ütlesid: "Kas siis Sina oled Jumala Poeg?" Tema ütles neile: "Jah, Ma olen!"',
        71: 'Siis nad ütlesid: "Mis tunnistust me veel vajame? Oleme ju ise seda kuulnud Tema suust!"',
    },
    23: {
        1: 'Ja kogu nende hulk tõusis ning viis Tema Pilaatuse juure.',
        2: 'Ja nad hakkasid kaebama Tema peale ning ütlesid: "Me oleme leidnud, et Tema rahvast eksitab ja keelab andmast maksuraha keisrile ning ütleb Enese Kuningas Kristuse olevat!"',
        3: 'Siis Pilaatus küsis Temalt ning ütles: "Kas Sina oled Juutide Kuningas?" Ja Ta vastas temale, üteldes: "Jah, olen!"',
        4: 'Pilaatus aga ütles ülempreestritele ja rahvale: "Ma ei leia sellest inimesest ühtki süüd!"',
        5: 'Aga nemad ajasid peale ja ütlesid: "Tema ässitab rahvast ja õpetab mööda kõike Juudamaad, alates Galileast kuni siiani!"',
        6: 'Aga kui Pilaatus seda kuulis, küsis ta, kas See Inimene ei ole mitte galilealane?',
        7: 'Ja saades teada, et Ta on Heroodese valitsuse alt, saatis ta Tema Heroodese juure, kes ka viibis Jeruusalemas neil päevil.',
        8: 'Kui siis Heroodes Jeesust nägi, sai ta väga rõõmsaks, sest ta oli hea meelega tahtnud Teda juba ammugi näha, kuna ta oli Temast palju kuulnud; ka lootis ta näha saada mõnd imetähte, mida Ta ehk teeb.',
        9: 'Ta küsis Temalt palju asju, aga Tema ei vastanud talle midagi.',
        10: 'Aga ülempreestrid ja kirjatundjad seisid ja kaebasid väga valjusti Tema peale.',
        11: 'Kui siis Heroodes oma sõjameestega teda oli halvaks pannud ja pilganud ning riietanud toreda riidega, saatis ta Tema tagasi Pilaatuse juure.',
        12: 'Ja sel päeval said Pilaatus ja Heroodes üksteisega sõbraks, sest enne nad olid olnud üksteise vihamehed.',
        13: 'Siis Pilaatus kutsus kokku ülempreestrid ning rahvaülemad ja rahva',
        14: 'ning ütles neile: "Te olete toonud selle inimese minu juure otsegu rahva eksitaja. Ja vaata, ma olen Teda üle kuulanud teie ees ega ole sellest inimesest leidnud ühtki süüd, milles te Teda süüdistate,',
        15: 'ega Heroodeski, vaid ta on Tema saatnud tagasi meie juure. Ja vaata, Tema pole teinud midagi, mis oleks surma väärt!',
        16: 'Sellepärast ma tahan Teda karistada ja vabaks lasta!"',
        17: 'Aga temal oli kohustuseks neile pühiks vabaks lasta üks vang.',
        18: 'Siis kogu hulk kisendas väga ning ütles: "Hukka ära, lase meile Barabas vabaks!"',
        19: 'See oli mingi linnas sündinud mässu ja tapmise pärast vangi heidetud.',
        20: 'Siis Pilaatus tõstis jälle häält nende vastu, tahtes vabaks lasta Jeesuse.',
        21: 'Aga nemad karjusid: "Löö risti, löö Ta risti!"',
        22: 'Siis ta ütles neile kolmat puhku: "Mis Ta siis on kurja teinud? Ma pole Temast leidnud ühtki surmasüüd. Sellepärast ma karistan teda ja lasen ta vabaks!"',
        23: 'Aga nad käisid peale, suure kisendamisega nõudes, et Jeesus löödaks risti. Ja nende hüüded võtsid võimust.',
        24: 'Siis Pilaatus tegi otsuse, et sünniks nende palve järele.',
        25: 'Ta laskis neile vabaks selle, kes mässamise ja tapmise pärast oli vangitorni heidetud ja keda nemad vabaks palusid. Aga Jeesuse ta andis nende meelevalla kätte.',
        26: 'Ja Teda välja viies said nad kätte kellegi Siimona Küreenest, kes tuli väljalt; ja tema peale nad panid risti, et ta seda kannaks Jeesuse järele.',
        27: 'Aga Teda järgis suur huik rahvast ja ka naisi, kes kaebasid ja Teda nutsid.',
        28: 'Siis Jeesus pöördus nende poole ja ütles: "Jeruusalema tütred, ärge nutke Mind, vaid nutke iseendid ja oma lapsi!',
        29: 'Sest vaata, päevad tulevad, mil üteldakse: Õndsad on sigimatud ja ihud, mis ei ole ilmale kannud, ja rinnad, mis ei ole imetanud!',
        30: 'Siis hakatakse ütlema mägedele: Langege meie peale! ja mäekinkudele: Katke meid!',
        31: 'Sest kui seda tehakse toore puuga, mis sünnib siis kuivaga!"',
        32: 'Aga ka kaks muud kurjategijat viidi ühes Temaga välja hukkamiseks.',
        33: 'Ja kui nad jõudsid sinna paika, mida hüütakse Pealaeks, lõid nad Tema sinna risti ja need kurjategijad, ühe paremale, teise vasakule poole.',
        34: 'Aga Jeesus ütles: "Isa, anna neile andeks, sest nad ei tea, mida nad teevad!" Ja nad jagasid Tema riided ning heitsid liisku nende pärast.',
        35: 'Ja rahvas seisis seal vaatamas, ja ka ülemad irvitasid ühes nendega ning ütlesid: "Muid Ta on aidanud, aidaku Iseennast, kui Ta on Jumala Võitu, see äravalitu!"',
        36: 'Ka sõjamehed naersid Teda, läksid Tema juure ja viisid Temale äädikat',
        37: 'ning ütlesid: "Kui Sina oled Juutide Kuningas, siis aita Iseennast!"',
        38: 'Aga oli ka pealkiri Tema kohal: "See on Juutide Kuningas!"',
        39: 'Siis teine poodud kurjategijaist pilkas Teda ning ütles: "Eks Sa ole Kristus? Aita Iseennast ja meid!"',
        40: 'Aga teine kostis ja sõitles teda ning ütles: "Kas sinagi ei karda Jumalat, kuna sa ise oled ju sama karistuse all?',
        41: 'Meie küll õiguse poolest, sest me saame kätte, mis meie teod on ära teeninud, aga Seesinane ei ole teinud midagi ebakohast!"',
        42: 'Ja ta ütles: "Jeesus, mõtle minule, kui Sa Oma Kuningriiki tuled!"',
        43: 'Ja Jeesus ütles temale: "Tõesti Ma ütlen sulle, täna pead sa Minuga olema paradiisis!"',
        44: 'Ja oli juba umbes kuues tund, siis tekkis pimedus üle kogu maa üheksandast tunnist saadik,',
        45: 'sest päike pimenes. Ja templi eesriie kärises keskelt lõhki!',
        46: 'Ja Jeesus kisendas suure häälega ning ütles: "Isa, Sinu kätte Ma annan Oma vaimu!" Ja kui Ta seda oli ütelnud, heitis Ta hinge.',
        47: 'Aga kui pealik nägi, mis sündis, andis ta Jumalale au ning ütles: "See inimene oli tõesti õige!"',
        48: 'Ja kui kõik rahvahulgad, kes olid kokku tulnud seda vaatama, nägid, mis sündis, lõid nad enestele vastu rindu ja läksid tagasi.',
        49: 'Aga kõik Ta tuttavad ja ka naised, kes olid järginud Teda Galileamaalt, seisid eemal ning nägid seda.',
        50: 'Ja vaata, mees, nimega Joosep, Suurkohtu liige, hea ja õiglane mees,',
        51: 'kes ei olnud ühes nõus nende otsusega ega teoga, Arimaatiast, Juuda rahva linnast, mees, kes ootas Jumala Riiki,',
        52: 'see läks Pilaatuse juure ja palus enesele Jeesuse ihu.',
        53: 'Ja ta võttis selle maha ja mähkis ta kallisse lõuendisse. Ja ta pani ta kaljusse raiutud hauda, kuhu ei olnud veel iialgi kedagi pandud.',
        54: 'Ja see oli valmistuspäev, ja hingamispäev oli tulemas.',
        55: 'Aga naised, kes Galileast olid teda järginud, käisid kaasas ja vaatasid hauda ja kuidas Tema ihu sinna pandi.',
        56: 'Ja kui nad olid tagasi tulnud, valmistasid nad lõhnarohte ja salvi. Aga hingamispäeval nad seisid rahul käsu järele.',
    },
    24: {
        1: 'Aga nädala esimesel päeval puhteajal läksid naised hauale, viies ühes lõhnarohud, mis nad olid valmistanud.',
        2: 'Ja nad leidsid kivi haualt ära veeretatud.',
        3: 'Siis nad läksid sisse, kuid ei leidnud mitte Issanda Jeesuse ihu.',
        4: 'Ja kui nad selle pärast kahevahel olid, vaata, siis seisis kaks meest nende kõrval säravais riideis!',
        5: 'Aga kui naised hakkasid kartma ja oma silmad maha lõid, ütlesid mehed neile: "Miks te elavat otsite surnute juurest?',
        6: 'Tema ei ole siin, vaid on üles tõusnud! Tuletage meele, mis Ta teile rääkis veel Galileas olles,',
        7: 'kui Ta teile ütles, et Inimese Poeg antakse patuste inimeste kätte ja lüüakse risti ja kolmandal päeval Ta tõuseb jälle üles!"',
        8: 'Siis nad tuletasid meele Tema sõnad',
        9: 'ja läksid tagasi haua juurest ja kuulutasid seda kõike neile üheteistkümnele ja kõigile teistele.',
        10: 'Aga Maarja Magdaleena ja Johanna ja Maarja, Jakoobuse ema, ja teised nende kaaslased jutustasid seda Apostlitele.',
        11: 'Ent need kõned olid nende meelest nagu tühi jutt ja nad ei uskunud naisi.',
        12: 'Aga Peetrus võttis kätte ja jooksis hauale. Ja kui ta kummargile sisse vaatas, nägi ta üksnes surnulinad maas olevat. Ja ta läks ära ja pani seda imeks, mis oli sündinud.',
        13: 'Ja vaata, kaks nende seast olid minemas selsamal päeval külasse, mis on ligi kuuskümmend vagu maad Jeruusalemast ja mille nimi on Emmaus.',
        14: 'Ja nad kõnelesid isekeskis kõigest, mis oli sündinud.',
        15: 'Ja nende kõneldes ja vaieldes lähenes ka Jeesus Ise neile ja käis nendega.',
        16: 'Aga nende silmad peeti, nii et nad Teda ei tunnud.',
        17: 'Ja Ta ütles neile: "Mis kõned need on, mis te käies kõnelete isekeskis?" Siis nad seisatasid kurvanäolistena.',
        18: 'Aga teine, nimega Kleopas, vastas ning ütles Temale: "Sinaks üksi elad kui võõras Jeruusalemas ega tea, mis neil päevil seal on sündinud?"',
        19: 'Ta küsis neilt: "Mis?" Aga nad ütlesid Temale: "See, mis sündis Jeesus Naatsaretlasega, Kes oli prohvet, vägev teolt ja sõnalt Jumala ja kõige rahva ees,',
        20: 'kuidas meie ülempreestrid ja vanemad on annud Ta surma mõista ja on Ta risti löönud.',
        21: 'Ent meie lootsime Tema olevat Selle, Kes Iisraeli rahva lunastab; aga peale selle kõige on täna kolmas päev, kui see sündis!',
        22: 'Ka mõned naised meie seast, kes puhteajal haual käisid, on meid ehmatanud:',
        23: 'kui nad Tema ihu ei leidnud, tulid nad ja ütlesid endid näinud olevat ka Inglite nägemust, kes ütlevad Tema elavat!',
        24: 'Ja mõningad neist, kes olid meiega, läksid hauale ja leidsid nõnda olevat, nagu naised olid ütelnud; kuid Teda Ennast nad ei näinud!"',
        25: 'Tema ütles neile: "Oh te mõistmatumad ja südamest pikaldased uskuma seda kõike, mis prohvetid on rääkinud!',
        26: 'Eks Kristus pidanud seda kannatama ja Oma auhiilgusesse minema?"',
        27: 'Ja Ta hakkas peale Moosesest ja kõigist prohveteist ja seletas neile, mis Temast kõigis kirjades oli üteldud.',
        28: 'Ja kui nad lähenesid külale, kuhu nad olid minemas, tegi Ta Enese eemale minema.',
        29: 'Ja nad käisid Temale peale ning ütlesid: "Jää meie juure, sest õhtu jõuab ja päev veereb!" Ja Tema läks sisse nende juure jääma.',
        30: 'Ja sündis, kui Ta nendega lauas istus, et Ta võttis leiva, õnnistas ja murdis ning andis neile.',
        31: 'Siis nende silmad läksid lahti ja nad tundsid Tema ära! Ja Tema kadus nende silmist.',
        32: 'Ja nad ütlesid üksteisele: "Eks meie süda põlenud meie sees, kui Ta teel meiega rääkis ja meile kirju seletas?"',
        33: 'Ja nad tõusid samal tunnil ja läksid tagasi Jeruusalemma ja leidsid koos olevat need üksteistkümmend ja kaaslased,',
        34: 'kes ütlesid: "Issand on tõesti üles tõusnud ja Siimonale ilmunud!"',
        35: 'Ja nemad ise jutustasid, mis teel oli sündinud ja kuidas nad Tema olid leiva murdmisest ära tunnud.',
        36: 'Aga kui nad seda rääkisid, seisis Jeesus ise nende keskel ja ütles neile: "Rahu olgu teile!"',
        37: 'Nemad kohkusid ja lõid kartma ning arvasid vaimu nägevat.',
        38: 'Ent Tema ütles neile: "Miks te olete nii väga ehmunud? Ja mispärast tõuseb niisuguseid mõtteid teie südamest?',
        39: 'Vaadake Mu käsi ja jalgu, et Mina see olen! Katsuge Mind kätega ja nähke, sest vaimul ei ole liha ega luid, nõnda nagu te näete Minul olevat!"',
        40: 'Ja seda üteldes näitas Ta neile Oma käsi ja jalgu.',
        41: 'Aga kui nad rõõmu pärast veel ei uskunud ja imeks panid, ütles Ta neile: "Kas teil on siin midagi süüa?"',
        42: 'Ja nad panid Tema ette pala küpsetatud kala.',
        43: 'Ja Tema võttis ja sõi nende ees.',
        44: 'Siis Ta ütles neile: "Need on kõned, mis Ma teile rääkisin veel teie juures olles; sest kõik peab täide minema, mis on kirjutatud Minu kohta Moosese käsuõpetuses ja Prohveteis ja Lauludes!"',
        45: 'Siis Ta avas nende mõistuse, nõnda et nad kirjadest aru said.',
        46: 'Ja ta ütles neile: "Nõnda on kirjutatud ja nõnda pidi Kristus kannatama ja surnuist üles tõusma kolmandal päeval,',
        47: 'ja Tema nimel peab kuulutatama meeleparandust pattude andekssaamiseks kõigi rahvaste seas, alates Jeruusalemast.',
        48: 'Teie olete nende asjade tunnistajad!',
        49: 'Ja vaata, Mina läkitan teie peale Oma Isa tõotuse! Ent teie jääge sellesse linna seni, kuni teid ehitakse väega kõrgest!"',
        50: 'Siis Ta viis nad välja Betaania lähedale ja tõstis Oma käed üles ja õnnistas neid.',
        51: 'Ja sündis, et Ta neid õnnistades lahkus neist ja võeti üles taevasse.',
        52: 'Ja nemad kummardasid Teda ning läksid tagasi Jeruusalemma suure rõõmuga',
        53: 'ja olid alati pühakojas, tänades Jumalat!',
    },
}
